import { Client } from '@modelcontextprotocol/sdk/client/index.js';
import { StdioClientTransport } from '@modelcontextprotocol/sdk/client/stdio.js';
import { execFileSync } from 'node:child_process';
import { createRequire } from 'node:module';
import { dirname, isAbsolute, join, relative } from 'node:path';

import {
  GraftInvalidPayloadError,
  GraftNoTextContentError,
  GraftPackageNotFoundError,
  GraftToolExecutionError,
} from '../domain/errors.js';

const require = createRequire(import.meta.url);

const GRAFT_PACKAGE_SPECIFIER = '@flyingrobots/graft';
const GRAFT_PACKAGE_JSON_SPECIFIER = '@flyingrobots/graft/package.json';
const GRAFT_BIN_PATH = 'bin/graft.js';
const GRAFT_SERVE_COMMAND = 'serve';
const GRAFT_FILE_OUTLINE_TOOL = 'file_outline';
const GRAFT_DIFF_TOOL = 'graft_diff';
const GRAFT_PROJECTION_REFUSED = 'refused';

type JsonPrimitive = string | number | boolean | null;
type JsonValue = JsonPrimitive | readonly JsonValue[] | JsonObject;

interface JsonObject {
  readonly [key: string]: JsonValue | undefined;
}

export interface GraftOutlineItem {
  readonly kind: string;
  readonly name: string;
  readonly signature?: string;
  readonly startLine: number;
  readonly endLine: number;
}

export interface GraftInfo {
  readonly path: string;
  readonly relativePath: string;
  readonly dirty: boolean;
  readonly outlineItems: readonly GraftOutlineItem[];
  readonly changeLines: readonly string[];
  readonly notice?: string;
  readonly error?: string;
}

export interface GraftJumpEntry {
  readonly symbol: string;
  readonly kind: string;
  readonly start: number;
  readonly end: number;
}

interface GraftDiffEntry {
  readonly name: string;
  readonly kind: string;
}

export interface GraftFileOutlineResult {
  readonly jumpTable?: readonly GraftJumpEntry[];
  readonly projection?: string;
  readonly reason?: string;
}

export interface GraftStructDiffResult {
  readonly files: ReadonlyArray<{
    readonly path: string;
    readonly summary: string;
    readonly diff: {
      readonly added: readonly GraftDiffEntry[];
      readonly changed: readonly GraftDiffEntry[];
      readonly removed: readonly GraftDiffEntry[];
    };
  }>;
}

interface GraftMcpConnection {
  readonly workspaceRoot: string;
  readonly client: Client;
  readonly transport: StdioClientTransport;
}

interface GraftTextBlock {
  readonly type: string;
  readonly text?: string;
}

interface GraftToolResult {
  readonly isError?: boolean;
  readonly structuredContent?: JsonValue;
  readonly content?: readonly GraftTextBlock[];
}

let graftConnection: GraftMcpConnection | undefined;
let graftConnectionPromise: Promise<GraftMcpConnection> | undefined;
let graftCliPath: string | undefined;

export async function loadGraftInfo(workspaceRoot: string, filePath: string, dirty: boolean): Promise<GraftInfo> {
  const relativePath = relative(workspaceRoot, filePath).replace(/\\/g, '/');
  if (relativePath.startsWith('..') || isAbsolute(relativePath)) {
    return {
      path: filePath,
      relativePath: filePath,
      dirty,
      outlineItems: [],
      changeLines: ['outside workspace root'],
      error: 'Graft only runs against files inside the launch workspace.',
    };
  }

  let outlineItems: readonly GraftOutlineItem[] = [];
  let error: string | undefined;

  try {
    const outline = decodeGraftFileOutlineResult(await callGraftTool(
      workspaceRoot,
      GRAFT_FILE_OUTLINE_TOOL,
      { path: relativePath },
    ));
    if (outline.projection === GRAFT_PROJECTION_REFUSED) {
      error = outline.reason ?? 'outline refused';
    } else {
      outlineItems = (outline.jumpTable ?? []).map((entry) => ({
        kind: entry.kind,
        name: entry.symbol,
        startLine: entry.start,
        endLine: entry.end,
      }));
    }
  } catch (cause) {
    error = `graft outline failed: ${cause instanceof Error ? cause.message : String(cause)}`;
  }

  return {
    path: filePath,
    relativePath,
    dirty,
    outlineItems,
    changeLines: await loadGraftChanges(workspaceRoot, relativePath),
    ...(dirty ? { notice: 'saved file only; unsaved edits are not reflected' } : {}),
    ...(error != null ? { error } : {}),
  };
}

export function failedGraftInfo(
  workspaceRoot: string,
  filePath: string,
  dirty: boolean,
  message: string,
): GraftInfo {
  return {
    path: filePath,
    relativePath: relative(workspaceRoot, filePath).replace(/\\/g, '/'),
    dirty,
    outlineItems: [],
    changeLines: [],
    error: `graft request failed: ${message}`,
    ...(dirty ? { notice: 'saved file only; unsaved edits are not reflected' } : {}),
  };
}

export async function closeGraftConnection(): Promise<void> {
  const connection = graftConnection;
  graftConnection = undefined;
  if (connection == null) {
    return;
  }

  await connection.client.close().catch(() => undefined);
  await connection.transport.close().catch(() => undefined);
}

async function loadGraftChanges(workspaceRoot: string, relativePath: string): Promise<readonly string[]> {
  if (!workspaceHasHead(workspaceRoot)) {
    return ['no git baseline yet'];
  }

  try {
    const diff = decodeGraftStructDiffResult(await callGraftTool(
      workspaceRoot,
      GRAFT_DIFF_TOOL,
      { path: relativePath },
    ));
    const file = diff.files.find((entry) => entry.path === relativePath);
    if (file == null) {
      return ['no structural changes vs HEAD'];
    }

    const lines = [
      file.summary.replace(`${file.path} | `, ''),
      ...file.diff.added.slice(0, 2).map((entry) => `+ ${entry.kind} ${entry.name}`),
      ...file.diff.changed.slice(0, 2).map((entry) => `~ ${entry.kind} ${entry.name}`),
      ...file.diff.removed.slice(0, 2).map((entry) => `- ${entry.kind} ${entry.name}`),
    ];

    return lines.length > 0 ? lines : ['no structural changes vs HEAD'];
  } catch (cause) {
    return [`graft diff failed: ${cause instanceof Error ? cause.message : String(cause)}`];
  }
}

function workspaceHasHead(workspaceRoot: string): boolean {
  try {
    execFileSync('git', ['rev-parse', '--verify', 'HEAD'], {
      cwd: workspaceRoot,
      encoding: 'utf8',
      stdio: ['ignore', 'pipe', 'pipe'],
    });
    return true;
  } catch {
    return false;
  }
}

async function ensureGraftConnection(workspaceRoot: string): Promise<GraftMcpConnection> {
  if (graftConnection?.workspaceRoot === workspaceRoot) {
    return graftConnection;
  }

  if (graftConnectionPromise != null) {
    const pending = await graftConnectionPromise;
    if (pending.workspaceRoot === workspaceRoot) {
      return pending;
    }
  }

  if (graftConnection != null) {
    await closeGraftConnection();
  }

  const transport = new StdioClientTransport({
    command: process.execPath,
    args: [resolveGraftCliPath(), GRAFT_SERVE_COMMAND],
    cwd: workspaceRoot,
    env: processEnvRecord(),
    stderr: 'pipe',
  });
  const client = new Client({
    name: 'jedit',
    version: '0.0.0',
  });

  const connectionPromise = (async () => {
    try {
      await client.connect(transport);
      const connection = {
        workspaceRoot,
        client,
        transport,
      };
      graftConnection = connection;
      return connection;
    } catch (cause) {
      await transport.close().catch(() => undefined);
      throw cause;
    } finally {
      graftConnectionPromise = undefined;
    }
  })();

  graftConnectionPromise = connectionPromise;
  return connectionPromise;
}

function resolveGraftCliPath(): string {
  if (graftCliPath != null) {
    return graftCliPath;
  }

  try {
    graftCliPath = join(dirname(require.resolve(GRAFT_PACKAGE_JSON_SPECIFIER)), GRAFT_BIN_PATH);
    return graftCliPath;
  } catch (cause) {
    throw new GraftPackageNotFoundError(`${GRAFT_PACKAGE_SPECIFIER} is not installed: ${cause instanceof Error ? cause.message : String(cause)}`);
  }
}

async function callGraftTool(
  workspaceRoot: string,
  name: string,
  args: Record<string, string | number | boolean | null>,
): Promise<JsonValue> {
  const connection = await ensureGraftConnection(workspaceRoot);
  const result = await connection.client.callTool({
    name,
    arguments: args,
  }) as GraftToolResult;

  if (result.isError === true) {
    throw new GraftToolExecutionError(parseGraftErrorResult(result));
  }

  return parseGraftToolResult(result);
}

function parseGraftErrorResult(result: GraftToolResult): string {
  if (result.structuredContent !== undefined) {
    return String(result.structuredContent);
  }

  return result.content
    ?.find((block) => block.type === 'text')
    ?.text ?? 'Graft tool returned an error';
}

function parseGraftToolResult(result: GraftToolResult): JsonValue {
  if (result.structuredContent !== undefined) {
    return result.structuredContent;
  }

  const text = result.content
    ?.find((block) => block.type === 'text')
    ?.text;

  if (text == null) {
    throw new GraftNoTextContentError('No text content in MCP result');
  }

  const parsed: JsonValue = JSON.parse(text);
  return parsed;
}

export function decodeGraftFileOutlineResult(value: JsonValue): GraftFileOutlineResult {
  const result = asJsonObject(value, 'file_outline');
  return {
    ...(result['jumpTable'] !== undefined ? { jumpTable: decodeGraftJumpTable(result['jumpTable'], 'jumpTable') } : {}),
    ...(result['projection'] !== undefined ? { projection: asString(result['projection'], 'projection') } : {}),
    ...(result['reason'] !== undefined ? { reason: asString(result['reason'], 'reason') } : {}),
  };
}

export function decodeGraftStructDiffResult(value: JsonValue): GraftStructDiffResult {
  const result = asJsonObject(value, 'graft_diff');
  return {
    files: asArray(result['files'], 'files').map((file, index) => decodeGraftDiffFile(file, `files[${String(index)}]`)),
  };
}

function decodeGraftJumpTable(value: JsonValue, path: string): readonly GraftJumpEntry[] {
  return asArray(value, path).map((entry, index) => decodeGraftJumpEntry(entry, `${path}[${String(index)}]`));
}

function decodeGraftJumpEntry(value: JsonValue, path: string): GraftJumpEntry {
  const entry = asJsonObject(value, path);
  return {
    symbol: asString(entry['symbol'], `${path}.symbol`),
    kind: asString(entry['kind'], `${path}.kind`),
    start: asNumber(entry['start'], `${path}.start`),
    end: asNumber(entry['end'], `${path}.end`),
  };
}

function decodeGraftDiffFile(value: JsonValue, path: string): GraftStructDiffResult['files'][number] {
  const file = asJsonObject(value, path);
  const diff = asJsonObject(file['diff'], `${path}.diff`);
  return {
    path: asString(file['path'], `${path}.path`),
    summary: asString(file['summary'], `${path}.summary`),
    diff: {
      added: decodeGraftDiffEntries(diff['added'], `${path}.diff.added`),
      changed: decodeGraftDiffEntries(diff['changed'], `${path}.diff.changed`),
      removed: decodeGraftDiffEntries(diff['removed'], `${path}.diff.removed`),
    },
  };
}

function decodeGraftDiffEntries(value: JsonValue | undefined, path: string): readonly GraftDiffEntry[] {
  return asArray(value, path).map((entry, index) => decodeGraftDiffEntry(entry, `${path}[${String(index)}]`));
}

function decodeGraftDiffEntry(value: JsonValue, path: string): GraftDiffEntry {
  const entry = asJsonObject(value, path);
  return {
    kind: asString(entry['kind'], `${path}.kind`),
    name: asString(entry['name'], `${path}.name`),
  };
}

function asJsonObject(value: JsonValue | undefined, path: string): JsonObject {
  if (!isJsonObject(value)) {
    throw new GraftInvalidPayloadError(`${path} must be an object`);
  }
  return value;
}

function isJsonObject(value: JsonValue | undefined): value is JsonObject {
  return typeof value === 'object' && value != null && !Array.isArray(value);
}

function asArray(value: JsonValue | undefined, path: string): readonly JsonValue[] {
  if (!Array.isArray(value)) {
    throw new GraftInvalidPayloadError(`${path} must be an array`);
  }
  return value;
}

function asString(value: JsonValue | undefined, path: string): string {
  if (typeof value !== 'string') {
    throw new GraftInvalidPayloadError(`${path} must be a string`);
  }
  return value;
}

function asNumber(value: JsonValue | undefined, path: string): number {
  if (typeof value !== 'number' || !Number.isFinite(value)) {
    throw new GraftInvalidPayloadError(`${path} must be a finite number`);
  }
  return value;
}

function processEnvRecord(): Record<string, string> {
  return Object.fromEntries(
    Object.entries(process.env).filter((entry): entry is [string, string] => entry[1] !== undefined),
  );
}

import type {
  CreateBufferWorldlineExecution,
  CreateCheckpointExecution,
  JeditWorldlineSession,
  ReplaceRangeAsTickExecution,
} from '../app/jedit-contract-runtime.js';
import type { WorldlineSnapshotReadingEnvelope } from '../app/jedit-observer-runtime.js';
import type { TextWindowReadingEnvelope } from '../app/jedit-observer-runtime.js';
import type {
  MutationOperationMap,
  QueryOperationMap,
} from '../generated/jedit/hot-text-runtime.types.generated.js';
import type { EchoWasmKernelTransport } from '../ports/echo-kernel-transport.js';
import type { JeditOpticClient } from '../ports/jedit-optic-client.js';
import {
  CREATE_BUFFER_WORLDLINE_OPERATION,
  CREATE_CHECKPOINT_OPERATION,
  decodeJeditIntentResponse,
  decodeJeditObserveResponse,
  encodeJeditIntentRequest,
  encodeJeditObserveRequest,
  JEDIT_INTENT_REQUEST_KIND,
  JEDIT_OBSERVE_REQUEST_KIND,
  JEDIT_TRANSPORT_STATUS_OBSTRUCTED,
  REPLACE_RANGE_AS_TICK_OPERATION,
  TEXT_WINDOW_OPERATION,
  toCreateBufferWorldlineExecution,
  toCreateCheckpointExecution,
  toReplaceRangeAsTickExecution,
  toTextWindowReadingEnvelope,
  toWorldlineSnapshotReadingEnvelope,
  WORLDLINE_SNAPSHOT_OPERATION,
  type JeditIntentRequest,
  type JeditIntentResponse,
  type JeditObserveRequest,
  type JeditObserveResponse,
  type JeditTransportObstruction,
} from './jedit-echo-optic-codec.js';

type CreateBufferWorldlineInput = MutationOperationMap['createBufferWorldline']['input'];
type ReplaceRangeAsTickInput = MutationOperationMap['replaceRangeAsTick']['input'];
type CreateCheckpointInput = MutationOperationMap['createCheckpoint']['input'];
type WorldlineSnapshotInput = QueryOperationMap['worldlineSnapshot']['input'];
type TextWindowInput = QueryOperationMap['textWindow']['input'];

export class JeditOpticTransportObstructionError extends Error {
  public readonly operationName: string;
  public readonly obstruction: JeditTransportObstruction;

  public constructor(operationName: string, obstruction: JeditTransportObstruction) {
    super(`Jedit optic transport obstructed ${operationName}: ${obstruction.message}`);
    this.name = 'JeditOpticTransportObstructionError';
    this.operationName = operationName;
    this.obstruction = obstruction;
  }
}

export class JeditOpticTransportProtocolError extends Error {
  public constructor(message: string) {
    super(message);
    this.name = 'JeditOpticTransportProtocolError';
  }
}

export function createEchoTransportJeditOpticClient(
  transport: EchoWasmKernelTransport,
): JeditOpticClient {
  return {
    createBufferWorldline(input: CreateBufferWorldlineInput): CreateBufferWorldlineExecution {
      const response = submitIntent(transport, {
        kind: JEDIT_INTENT_REQUEST_KIND,
        operationName: CREATE_BUFFER_WORLDLINE_OPERATION,
        input,
      });
      if (response.status === JEDIT_TRANSPORT_STATUS_OBSTRUCTED) {
        throw new JeditOpticTransportObstructionError(response.operationName, response.obstruction);
      }
      if (response.operationName !== CREATE_BUFFER_WORLDLINE_OPERATION) {
        throwUnexpectedOperation(CREATE_BUFFER_WORLDLINE_OPERATION, response.operationName);
      }
      return toCreateBufferWorldlineExecution(response.execution);
    },
    replaceRangeAsTick(
      session: JeditWorldlineSession,
      input: ReplaceRangeAsTickInput,
    ): ReplaceRangeAsTickExecution {
      const response = submitIntent(transport, {
        kind: JEDIT_INTENT_REQUEST_KIND,
        operationName: REPLACE_RANGE_AS_TICK_OPERATION,
        session,
        input,
      });
      if (response.status === JEDIT_TRANSPORT_STATUS_OBSTRUCTED) {
        throw new JeditOpticTransportObstructionError(response.operationName, response.obstruction);
      }
      if (response.operationName !== REPLACE_RANGE_AS_TICK_OPERATION) {
        throwUnexpectedOperation(REPLACE_RANGE_AS_TICK_OPERATION, response.operationName);
      }
      return toReplaceRangeAsTickExecution(response.execution);
    },
    createCheckpoint(
      session: JeditWorldlineSession,
      input: CreateCheckpointInput,
    ): CreateCheckpointExecution {
      const response = submitIntent(transport, {
        kind: JEDIT_INTENT_REQUEST_KIND,
        operationName: CREATE_CHECKPOINT_OPERATION,
        session,
        input,
      });
      if (response.status === JEDIT_TRANSPORT_STATUS_OBSTRUCTED) {
        throw new JeditOpticTransportObstructionError(response.operationName, response.obstruction);
      }
      if (response.operationName !== CREATE_CHECKPOINT_OPERATION) {
        throwUnexpectedOperation(CREATE_CHECKPOINT_OPERATION, response.operationName);
      }
      return toCreateCheckpointExecution(response.execution);
    },
    worldlineSnapshot(
      session: JeditWorldlineSession,
      frontierRef: string,
      input: WorldlineSnapshotInput,
    ): WorldlineSnapshotReadingEnvelope {
      const response = observe(transport, {
        kind: JEDIT_OBSERVE_REQUEST_KIND,
        operationName: WORLDLINE_SNAPSHOT_OPERATION,
        session,
        frontierRef,
        input,
      });
      if (response.status === JEDIT_TRANSPORT_STATUS_OBSTRUCTED) {
        throw new JeditOpticTransportObstructionError(response.operationName, response.obstruction);
      }
      if (response.operationName !== WORLDLINE_SNAPSHOT_OPERATION) {
        throwUnexpectedOperation(WORLDLINE_SNAPSHOT_OPERATION, response.operationName);
      }
      return toWorldlineSnapshotReadingEnvelope(response.envelope);
    },
    textWindow(
      session: JeditWorldlineSession,
      frontierRef: string,
      input: TextWindowInput,
    ): TextWindowReadingEnvelope {
      const response = observe(transport, {
        kind: JEDIT_OBSERVE_REQUEST_KIND,
        operationName: TEXT_WINDOW_OPERATION,
        session,
        frontierRef,
        input,
      });
      if (response.status === JEDIT_TRANSPORT_STATUS_OBSTRUCTED) {
        throw new JeditOpticTransportObstructionError(response.operationName, response.obstruction);
      }
      if (response.operationName !== TEXT_WINDOW_OPERATION) {
        throwUnexpectedOperation(TEXT_WINDOW_OPERATION, response.operationName);
      }
      return toTextWindowReadingEnvelope(response.envelope);
    },
  };
}

function submitIntent(
  transport: EchoWasmKernelTransport,
  request: JeditIntentRequest,
): JeditIntentResponse {
  return decodeJeditIntentResponse(
    transport.submitIntentBytes(encodeJeditIntentRequest(request)),
  );
}

function observe(
  transport: EchoWasmKernelTransport,
  request: JeditObserveRequest,
): JeditObserveResponse {
  return decodeJeditObserveResponse(
    transport.observeBytes(encodeJeditObserveRequest(request)),
  );
}

function throwUnexpectedOperation(expected: string, actual: string): never {
  throw new JeditOpticTransportProtocolError(
    `Expected ${expected} transport response, received ${actual}.`,
  );
}

import * as fs from 'node:fs/promises';
import { TITLE_SCENE_SHAPE_KIND, type TitleScene, type TitleSceneCameraPlacement, type TitleSceneObject } from '../ui/title-scene.js';
import type { TitleMesh } from '../ui/title-mesh.js';

export interface TitleSceneJson {
  readonly camera?: {
    readonly angle?: number;
    readonly radius?: number;
  };
  readonly objects?: ReadonlyArray<{
    readonly kind: string;
    readonly position: readonly [number, number, number];
    readonly radius: number;
    readonly footprintRadius?: number;
    readonly height?: number;
    readonly color: readonly [number, number, number];
    readonly reflectivity: number;
  }>;
}

export async function loadTitleSceneFromFile(path: string, mesh: TitleMesh | undefined): Promise<TitleScene> {
  const content = await fs.readFile(path, 'utf8');
  const json = JSON.parse(content) as TitleSceneJson;
  return parseTitleSceneJson(json, mesh);
}

export function parseTitleSceneJson(json: TitleSceneJson, mesh: TitleMesh | undefined): TitleScene {
  const camera: TitleSceneCameraPlacement = {
    angle: json.camera?.angle ?? 0,
    radius: json.camera?.radius ?? 8.5,
  };

  const objects: TitleSceneObject[] = [];

  for (const obj of (json.objects ?? [])) {
    if (obj.kind === TITLE_SCENE_SHAPE_KIND.Sphere) {
      objects.push({
        kind: TITLE_SCENE_SHAPE_KIND.Sphere,
        position: obj.position,
        radius: obj.radius,
        footprintRadius: obj.footprintRadius ?? obj.radius,
        height: obj.height ?? obj.radius * 2,
        color: obj.color,
        reflectivity: obj.reflectivity,
      });
    } else if (obj.kind === TITLE_SCENE_SHAPE_KIND.Column) {
      objects.push({
        kind: TITLE_SCENE_SHAPE_KIND.Column,
        position: obj.position,
        radius: obj.radius,
        footprintRadius: obj.footprintRadius ?? obj.radius,
        height: obj.height ?? obj.radius * 2,
        color: obj.color,
        reflectivity: obj.reflectivity,
      });
    } else if (obj.kind === TITLE_SCENE_SHAPE_KIND.Mesh && mesh != null) {
      objects.push({
        kind: TITLE_SCENE_SHAPE_KIND.Mesh,
        mesh,
        position: obj.position,
        radius: obj.radius,
        footprintRadius: obj.footprintRadius ?? obj.radius,
        height: obj.height ?? mesh.height,
        color: obj.color,
        reflectivity: obj.reflectivity,
      });
    }
  }

  return { camera, objects };
}

import type { KeyMsg } from '@flyingrobots/bijou-tui';
import {
  EditorState,
} from '../domain/editor-state.js';

export function updateInsertMode(
  editor: EditorState,
  msg: KeyMsg,
  viewportWidth: number,
  viewportHeight: number,
  allowTabIndent: boolean,
): EditorState {
  if (editor.readOnly) {
    return editor;
  }
  const viewport = { width: Math.max(1, viewportWidth), height: Math.max(1, viewportHeight) };

  if (msg.key === 'escape') {
    return editor.with({ mode: 'normal' }).ensureVisible(viewport.width, viewport.height);
  }
  if (msg.key === 'left') {
    return editor.applyMotion({ type: 'char', direction: 'left' }).ensureVisible(viewport.width, viewport.height);
  }
  if (msg.key === 'right') {
    return editor.applyMotion({ type: 'char', direction: 'right' }).ensureVisible(viewport.width, viewport.height);
  }
  if (msg.key === 'up') {
    return editor.applyMotion({ type: 'char', direction: 'up' }).ensureVisible(viewport.width, viewport.height);
  }
  if (msg.key === 'down') {
    return editor.applyMotion({ type: 'char', direction: 'down' }).ensureVisible(viewport.width, viewport.height);
  }
  if (msg.key === 'home') {
    return editor.applyMotion({ type: 'line', target: 'start' }).ensureVisible(viewport.width, viewport.height);
  }
  if (msg.key === 'end') {
    return editor.applyMotion({ type: 'line', target: 'end' }).ensureVisible(viewport.width, viewport.height);
  }
  if (msg.key === 'pageup') {
    return editor.applyMotion({ type: 'char', direction: 'up', delta: viewport.height }).ensureVisible(viewport.width, viewport.height);
  }
  if (msg.key === 'pagedown') {
    return editor.applyMotion({ type: 'char', direction: 'down', delta: viewport.height }).ensureVisible(viewport.width, viewport.height);
  }
  if (msg.key === 'backspace') {
    return editor.applyMutation({ type: 'backspace' }).ensureVisible(viewport.width, viewport.height);
  }
  if (msg.key === 'delete') {
    return editor.applyMutation({ type: 'delete', target: 'char' }).ensureVisible(viewport.width, viewport.height);
  }
  if (msg.key === 'enter') {
    return editor.applyMutation({ type: 'newline' }).ensureVisible(viewport.width, viewport.height);
  }
  if (allowTabIndent && msg.key === 'tab') {
    return editor.applyMutation({ type: 'insert', text: '  ' }).ensureVisible(viewport.width, viewport.height);
  }

  const inserted = keyToText(msg);
  if (inserted != null) {
    return editor.applyMutation({ type: 'insert', text: inserted }).ensureVisible(viewport.width, viewport.height);
  }

  return editor.ensureVisible(viewport.width, viewport.height);
}

export function updateNormalMode(
  editor: EditorState,
  msg: KeyMsg,
  viewportWidth: number,
  viewportHeight: number,
): EditorState {
  const viewport = { width: Math.max(1, viewportWidth), height: Math.max(1, viewportHeight) };

  if (msg.key === 'escape') {
    return editor.with({ pendingNormal: undefined }).ensureVisible(viewport.width, viewport.height);
  }

  if (editor.pendingNormal === 'd') {
    const cleared = editor.with({ pendingNormal: undefined });
    const operated = applyPendingOperator(cleared, 'delete', msg);
    if (operated != null) {
      return operated.ensureVisible(viewport.width, viewport.height);
    }
    return updateNormalMode(cleared, msg, viewport.width, viewport.height);
  }

  if (editor.pendingNormal === 'c') {
    const cleared = editor.with({ pendingNormal: undefined });
    const operated = applyPendingOperator(cleared, 'change', msg);
    if (operated != null) {
      return operated.ensureVisible(viewport.width, viewport.height);
    }
    return updateNormalMode(cleared, msg, viewport.width, viewport.height);
  }

  if (editor.pendingNormal === 'y') {
    const cleared = editor.with({ pendingNormal: undefined });
    const operated = applyPendingOperator(cleared, 'yank', msg);
    if (operated != null) {
      return operated.ensureVisible(viewport.width, viewport.height);
    }
    return updateNormalMode(cleared, msg, viewport.width, viewport.height);
  }

  if (editor.pendingNormal === 'g') {
    const cleared = editor.with({ pendingNormal: undefined });
    if (!msg.ctrl && !msg.alt && !msg.shift && msg.key === 'g') {
      return cleared.applyMotion({ type: 'document', target: 'top' }).ensureVisible(viewport.width, viewport.height);
    }
    return updateNormalMode(cleared, msg, viewport.width, viewport.height);
  }

  if (!msg.ctrl && !msg.alt && !msg.shift && msg.key === 'i') {
    return editor.with({ mode: 'insert' }).ensureVisible(viewport.width, viewport.height);
  }
  if (!msg.ctrl && !msg.alt && !msg.shift && msg.key === 'a') {
    return editor.applyMotion({ type: 'char', direction: 'right' }).with({ mode: 'insert' }).ensureVisible(viewport.width, viewport.height);
  }
  if (!msg.ctrl && !msg.alt && msg.shift && msg.key === 'a') {
    return editor.applyMotion({ type: 'line', target: 'end' }).with({ mode: 'insert' }).ensureVisible(viewport.width, viewport.height);
  }
  if (!msg.ctrl && !msg.alt && msg.shift && msg.key === 'i') {
    return editor.applyMotion({ type: 'line', target: 'first-non-whitespace' }).with({ mode: 'insert' }).ensureVisible(viewport.width, viewport.height);
  }
  if (!msg.ctrl && !msg.alt && !msg.shift && msg.key === 'o') {
    return editor.applyMutation({ type: 'newline' }).with({ mode: 'insert' }).ensureVisible(viewport.width, viewport.height);
    // Wait, openLineBelow/Above are slightly more complex. 
    // I should add them as specific mutations or keep them as methods.
  }
  // ... more mappings ...

  return editor.ensureVisible(viewport.width, viewport.height);
}

function applyPendingOperator(
  editor: EditorState,
  operator: 'change' | 'delete' | 'yank',
  msg: KeyMsg,
): EditorState | undefined {
  if (msg.ctrl || msg.alt) return undefined;

  if (!msg.shift) {
    if (operator === 'delete' && msg.key === 'd') return editor.applyMutation({ type: 'delete', target: 'line' });
    if (operator === 'change' && msg.key === 'c') return editor.applyMutation({ type: 'delete', target: 'line' }).with({ mode: 'insert' });
    if (operator === 'yank' && msg.key === 'y') return editor.applyMutation({ type: 'yank', target: 'line' });
  }

  return undefined;
}

function keyToText(msg: KeyMsg): string | undefined {
  if (msg.ctrl || msg.alt) return undefined;
  if (msg.key === 'space') return ' ';
  if (msg.key.length !== 1) return undefined;
  return msg.key;
}

import { createHash } from 'node:crypto';

import { createTextRange, materializeRoot } from '../domain/text-edit-contract.js';
import type { SaveCheckpointReceipt } from '../domain/save-checkpoint-contract.js';
import type { TickAdmissionReceipt } from '../domain/tick-admission-contract.js';
import type {
  CheckpointKind,
  BufferWorldline,
  Checkpoint,
  MutationOperationMap,
  QueryOperationMap,
  RopeHead,
  Tick,
  TickKind,
  TickReceiptRewriteKind,
  TickReceipt,
} from '../generated/jedit/hot-text-runtime.types.generated.js';
import {
  MutationOperationSchemas,
  QueryOperationSchemas,
} from '../generated/jedit/hot-text-runtime.zod.generated.js';
import type { HotTextBufferState, HotTextRuntimePort } from '../ports/hot-text-runtime.js';

const JEDIT_CONTRACT_RUNTIME_ERROR_WORLDLINE_MISMATCH = 1;
const JEDIT_CONTRACT_RUNTIME_ERROR_BASE_HEAD_MISMATCH = 2;

const WORLDLINE_ID_PREFIX = 'wl:';
const HEAD_ID_PREFIX = 'head:';
const ROOT_NODE_ID_PREFIX = 'root:';
const CHECKPOINT_ID_PREFIX = 'checkpoint:';
const TICK_ID_PREFIX = 'tick:';
const RECEIPT_ID_PREFIX = 'receipt:';
const TICK_KIND_TEXT_REWRITE: TickKind = 'TEXT_REWRITE';
const TICK_RECEIPT_REWRITE_KIND_REPLACE_RANGE_AS_TICK: TickReceiptRewriteKind = 'REPLACE_RANGE_AS_TICK';
const INITIAL_CHECKPOINT_KIND: CheckpointKind = 'INITIAL';
const EMPTY_LINE_COUNT = 1;

const UTF8_ENCODER = new TextEncoder();

type CreateBufferWorldlineInput = MutationOperationMap['createBufferWorldline']['input'];
type CreateBufferWorldlineResult = MutationOperationMap['createBufferWorldline']['result'];
type ReplaceRangeAsTickInput = MutationOperationMap['replaceRangeAsTick']['input'];
type ReplaceRangeAsTickResult = MutationOperationMap['replaceRangeAsTick']['result'];
type CreateCheckpointInput = MutationOperationMap['createCheckpoint']['input'];
type CreateCheckpointResult = MutationOperationMap['createCheckpoint']['result'];
type WorldlineSnapshotInput = QueryOperationMap['worldlineSnapshot']['input'];
type WorldlineSnapshotResult = QueryOperationMap['worldlineSnapshot']['result'];

export interface JeditWorldlineSession {
  readonly worldline: BufferWorldline;
  readonly state: HotTextBufferState;
  readonly tickMetadata: readonly TickMetadata[];
  readonly checkpointMetadata: readonly CheckpointMetadata[];
}

export interface CreateBufferWorldlineExecution {
  readonly nextSession: JeditWorldlineSession;
  readonly result: CreateBufferWorldlineResult;
}

export interface ReplaceRangeAsTickExecution {
  readonly nextSession: JeditWorldlineSession;
  readonly result?: ReplaceRangeAsTickResult;
}

export interface CreateCheckpointExecution {
  readonly nextSession: JeditWorldlineSession;
  readonly result?: CreateCheckpointResult;
}

interface TickMetadata {
  readonly tickId: number;
  readonly kind: TickKind;
  readonly author?: string;
}

interface CheckpointMetadata {
  readonly checkpointId: number;
  readonly kind: CreateCheckpointInput['kind'];
  readonly label?: string;
  readonly createdByTickId?: number;
}

export class JeditContractRuntimeError extends Error {
  public readonly code: number;

  public constructor(code: number, message: string) {
    super(message);
    this.name = 'JeditContractRuntimeError';
    this.code = code;
  }
}

export function createBufferWorldline(
  runtime: HotTextRuntimePort,
  input: CreateBufferWorldlineInput,
): CreateBufferWorldlineExecution {
  const parsedInput = MutationOperationSchemas.createBufferWorldline.input.parse(input);
  const initialText = parsedInput.initialText ?? '';
  const projectionPath = parsedInput.projectionPath ?? parsedInput.bufferKey;
  const initialState = runtime.createBuffer(projectionPath, initialText);
  const initialSession = createSession(parsedInput.bufferKey, projectionPath, initialState, [], []);

  if (!(parsedInput.createInitialCheckpoint ?? false)) {
    const result = MutationOperationSchemas.createBufferWorldline.result.parse({
      worldline: initialSession.worldline,
      head: toHeadRecord(initialSession),
    });
    return {
      nextSession: initialSession,
      result,
    };
  }

  const saved = runtime.saveCheckpoint(initialState);
  const metadata = saved.receipt == null
    ? []
    : [createCheckpointMetadata(saved.receipt, INITIAL_CHECKPOINT_KIND, undefined)];
  const nextSession = createSession(parsedInput.bufferKey, projectionPath, saved.nextState, [], metadata);
  const checkpoint = metadata[0] == null ? undefined : toCheckpointRecord(nextSession, metadata[0]);
  const result = MutationOperationSchemas.createBufferWorldline.result.parse({
    worldline: nextSession.worldline,
    head: toHeadRecord(nextSession),
    checkpoint,
  });

  return {
    nextSession,
    result,
  };
}

export function materializeWorldline(
  runtime: HotTextRuntimePort,
  session: JeditWorldlineSession,
): string {
  return runtime.materialize(session.state);
}

export function readWorldlineSnapshot(
  runtime: HotTextRuntimePort,
  session: JeditWorldlineSession,
  input: WorldlineSnapshotInput,
): WorldlineSnapshotResult {
  const parsedInput = QueryOperationSchemas.worldlineSnapshot.input.parse(input);
  ensureMatchingWorldline(session, parsedInput.worldlineId);

  return QueryOperationSchemas.worldlineSnapshot.result.parse({
    worldline: session.worldline,
    head: toHeadRecord(session),
    checkpoints: toCheckpointRecords(session),
    text: materializeWorldline(runtime, session),
  });
}

export function replaceRangeAsTick(
  runtime: HotTextRuntimePort,
  session: JeditWorldlineSession,
  input: ReplaceRangeAsTickInput,
): ReplaceRangeAsTickExecution {
  const parsedInput = MutationOperationSchemas.replaceRangeAsTick.input.parse(input);
  ensureMatchingWorldline(session, parsedInput.worldlineId);
  ensureMatchingBaseHead(session, parsedInput.baseHeadId);

  const baseHeadId = parsedInput.baseHeadId;
  const admission = runtime.admitReplaceRangeTick(
    session.state,
    createTextRange(parsedInput.startByte, parsedInput.endByte),
    parsedInput.insertText,
  );

  if (admission.receipt == null) {
    return {
      nextSession: createSessionFromExisting(session, admission.nextState, session.tickMetadata, session.checkpointMetadata),
    };
  }

  const tickMetadata = createTickMetadata(admission.receipt, parsedInput.author ?? undefined);
  const nextTickMetadata = [
    ...session.tickMetadata,
    tickMetadata,
  ];
  const nextSession = createSessionFromExisting(
    session,
    admission.nextState,
    nextTickMetadata,
    session.checkpointMetadata,
  );
  const tick = toTickRecord(nextSession, tickMetadata);
  const result = MutationOperationSchemas.replaceRangeAsTick.result.parse({
    worldline: nextSession.worldline,
    nextHead: toHeadRecord(nextSession),
    tick,
    receipt: toTickReceiptRecord(
      admission.receipt,
      baseHeadId,
      nextSession.worldline.canonicalHeadId,
      parsedInput.insertText,
    ),
  });

  return {
    nextSession,
    result,
  };
}

export function createCheckpoint(
  runtime: HotTextRuntimePort,
  session: JeditWorldlineSession,
  input: CreateCheckpointInput,
): CreateCheckpointExecution {
  const parsedInput = MutationOperationSchemas.createCheckpoint.input.parse(input);
  ensureMatchingWorldline(session, parsedInput.worldlineId);

  const saved = runtime.saveCheckpoint(session.state);
  if (saved.receipt == null) {
    return {
      nextSession: createSessionFromExisting(session, saved.nextState, session.tickMetadata, session.checkpointMetadata),
    };
  }

  const checkpointMetadata = createCheckpointMetadata(
    saved.receipt,
    parsedInput.kind,
    parsedInput.label ?? undefined,
  );
  const nextCheckpointMetadata = [
    ...session.checkpointMetadata,
    checkpointMetadata,
  ];
  const nextSession = createSessionFromExisting(
    session,
    saved.nextState,
    session.tickMetadata,
    nextCheckpointMetadata,
  );
  const checkpoint = toCheckpointRecord(nextSession, checkpointMetadata);
  const result = MutationOperationSchemas.createCheckpoint.result.parse({
    worldline: nextSession.worldline,
    head: toHeadRecord(nextSession),
    checkpoint,
  });

  return {
    nextSession,
    result,
  };
}

function createSession(
  bufferKey: string,
  projectionPath: string,
  state: HotTextBufferState,
  tickMetadata: readonly TickMetadata[],
  checkpointMetadata: readonly CheckpointMetadata[],
): JeditWorldlineSession {
  const worldlineId = toWorldlineId(projectionPath);
  const worldline: BufferWorldline = {
    worldlineId,
    bufferKey,
    canonicalHeadId: toHeadId(state.currentRoot.id),
    projectionPath,
  };

  return {
    worldline,
    state,
    tickMetadata: [...tickMetadata],
    checkpointMetadata: [...checkpointMetadata],
  };
}

function createSessionFromExisting(
  session: JeditWorldlineSession,
  state: HotTextBufferState,
  tickMetadata: readonly TickMetadata[],
  checkpointMetadata: readonly CheckpointMetadata[],
): JeditWorldlineSession {
  return createSession(
    session.worldline.bufferKey,
    session.worldline.projectionPath ?? session.worldline.bufferKey,
    state,
    tickMetadata,
    checkpointMetadata,
  );
}

function createTickMetadata(receipt: TickAdmissionReceipt, author: string | undefined): TickMetadata {
  return {
    tickId: receipt.tickId,
    kind: TICK_KIND_TEXT_REWRITE,
    author,
  };
}

function createCheckpointMetadata(
  receipt: SaveCheckpointReceipt,
  kind: CreateCheckpointInput['kind'],
  label: string | undefined,
): CheckpointMetadata {
  return {
    checkpointId: receipt.checkpointId,
    kind,
    label,
  };
}

function toCheckpointRecords(session: JeditWorldlineSession): Checkpoint[] {
  return session.checkpointMetadata.map((metadata) => toCheckpointRecord(session, metadata));
}

function toHeadRecord(session: JeditWorldlineSession): RopeHead {
  const text = materializeRoot(session.state.currentRoot);

  return {
    headId: toHeadId(session.state.currentRoot.id),
    worldlineId: session.worldline.worldlineId,
    rootNodeId: toRootNodeId(session.state.currentRoot.id),
    byteLength: byteLength(text),
    lineCount: lineCount(text),
    utf16Length: text.length,
    equivalenceDigest: digest(text),
  };
}

function toTickRecord(session: JeditWorldlineSession, metadata: TickMetadata): Tick {
  return {
    tickId: toTickId(metadata.tickId),
    worldlineId: session.worldline.worldlineId,
    kind: metadata.kind,
    sequenceNumber: metadata.tickId,
    author: metadata.author,
  };
}

function toTickReceiptRecord(
  receipt: TickAdmissionReceipt,
  baseHeadId: string,
  nextHeadId: string,
  insertText: string,
): TickReceipt {
  const deletedByteLength = receipt.replaceReceipt.replaced.end.byte - receipt.replaceReceipt.replaced.start.byte;

  return {
    receiptId: toReceiptId(receipt.tickId),
    tickId: toTickId(receipt.tickId),
    baseHeadId,
    nextHeadId,
    rewriteKind: TICK_RECEIPT_REWRITE_KIND_REPLACE_RANGE_AS_TICK,
    startByte: receipt.replaceReceipt.replaced.start.byte,
    endByte: receipt.replaceReceipt.replaced.end.byte,
    insertedByteLength: byteLength(insertText),
    deletedByteLength,
    summary: `replace ${receipt.replaceReceipt.replaced.start.byte}..${receipt.replaceReceipt.replaced.end.byte}`,
  };
}

function toCheckpointRecord(
  session: JeditWorldlineSession,
  metadata: CheckpointMetadata,
): Checkpoint {
  const checkpoint = session.state.checkpoints.find((entry) => entry.id === metadata.checkpointId);
  const headId = checkpoint == null
    ? session.worldline.canonicalHeadId
    : toHeadId(checkpoint.rootId);

  return {
    checkpointId: toCheckpointId(metadata.checkpointId),
    worldlineId: session.worldline.worldlineId,
    headId,
    kind: metadata.kind,
    label: metadata.label,
    createdByTickId: metadata.createdByTickId == null ? undefined : toTickId(metadata.createdByTickId),
  };
}

function ensureMatchingWorldline(session: JeditWorldlineSession, worldlineId: string): void {
  if (session.worldline.worldlineId !== worldlineId) {
    throw new JeditContractRuntimeError(
      JEDIT_CONTRACT_RUNTIME_ERROR_WORLDLINE_MISMATCH,
      `Worldline mismatch: expected ${session.worldline.worldlineId}, received ${worldlineId}.`,
    );
  }
}

function ensureMatchingBaseHead(session: JeditWorldlineSession, baseHeadId: string): void {
  if (session.worldline.canonicalHeadId !== baseHeadId) {
    throw new JeditContractRuntimeError(
      JEDIT_CONTRACT_RUNTIME_ERROR_BASE_HEAD_MISMATCH,
      `Base head mismatch: expected ${session.worldline.canonicalHeadId}, received ${baseHeadId}.`,
    );
  }
}

function toWorldlineId(path: string): string {
  return `${WORLDLINE_ID_PREFIX}${path}`;
}

function toHeadId(rootId: number): string {
  return `${HEAD_ID_PREFIX}${rootId}`;
}

function toRootNodeId(rootId: number): string {
  return `${ROOT_NODE_ID_PREFIX}${rootId}`;
}

function toCheckpointId(checkpointId: number): string {
  return `${CHECKPOINT_ID_PREFIX}${checkpointId}`;
}

function toTickId(tickId: number): string {
  return `${TICK_ID_PREFIX}${tickId}`;
}

function toReceiptId(tickId: number): string {
  return `${RECEIPT_ID_PREFIX}${toTickId(tickId)}`;
}

function byteLength(text: string): number {
  return UTF8_ENCODER.encode(text).length;
}

function lineCount(text: string): number {
  if (text.length === 0) {
    return EMPTY_LINE_COUNT;
  }

  return text.split('\n').length;
}

function digest(text: string): string {
  return createHash('sha256').update(text, 'utf8').digest('hex');
}

