import { basename, join } from 'node:path';
import { open, type FileHandle } from 'node:fs/promises';
import type { Cmd, RuntimeIssue } from '@flyingrobots/bijou-tui';

export interface ProfilerFrame {
  readonly time: number;
  readonly frameTimeMs: number;
  readonly columns: number;
  readonly rows: number;
}

export interface ProfilerState {
  readonly active: boolean;
  readonly filePath?: string;
  readonly fileHandle?: FileHandle;
}

export type ProfilerMsg =
  | { type: 'profiler-started'; filePath: string; fileHandle: FileHandle }
  | { type: 'profiler-stopped' };

export type ProfilerEffectMsg = ProfilerMsg | { type: 'runtime-issue'; issue: RuntimeIssue };

export function createInitialProfilerState(): ProfilerState {
  return { active: false };
}

export function reduceProfilerMsg(state: ProfilerState, msg: ProfilerMsg): ProfilerState {
  if (msg.type === 'profiler-started') {
    return { active: true, filePath: msg.filePath, fileHandle: msg.fileHandle };
  }
  if (msg.type === 'profiler-stopped') {
    return { active: false };
  }
  return state;
}

export function toggleProfiler(
  state: ProfilerState,
  workspaceRoot: string,
): [ProfilerState, Cmd<ProfilerEffectMsg>[]] {
  if (state.active && state.fileHandle != null) {
    const fileName = state.filePath ? basename(state.filePath) : 'profile.jsonl';
    // We deactivate immediately to prevent race conditions during close
    const nextState = { ...state, active: false };
    const activeHandle = state.fileHandle;
    return [nextState, [
      async (): Promise<ProfilerEffectMsg> => {
        try {
          await activeHandle.close();
          const stopped: ProfilerMsg = { type: 'profiler-stopped' };
          return stopped;
        } catch (err) {
          return {
            type: 'runtime-issue',
            issue: {
              message: `Failed to close profile: ${String(err)}`,
              level: 'error',
              source: 'command',
              atMs: Date.now(),
            },
          };
        }
      },
      (): ProfilerEffectMsg => {
        return {
          type: 'runtime-issue',
          issue: {
            message: `Profile trace saved to ${fileName}`,
            level: 'warning',
            source: 'command',
            atMs: Date.now(),
          },
        };
      },
    ]];
  }

  return [state, [
    async (): Promise<ProfilerEffectMsg> => {
      try {
        const fileName = `raytracer-profile-${Date.now()}.jsonl`;
        const filePath = join(workspaceRoot, fileName);
        const fileHandle = await open(filePath, 'a');
        const started: ProfilerMsg = { type: 'profiler-started', filePath, fileHandle };
        return started;
      } catch (err) {
        return {
          type: 'runtime-issue',
          issue: {
            message: `Failed to start profile: ${String(err)}`,
            level: 'error',
            source: 'command',
            atMs: Date.now(),
          },
        };
      }
    }
  ]];
}

export function streamProfilerFrame(
  state: ProfilerState,
  frame: ProfilerFrame,
): Cmd<ProfilerEffectMsg> | undefined {
  if (!state.active || state.fileHandle == null) {
    return undefined;
  }

  const activeHandle = state.fileHandle;
  return async (): Promise<ProfilerEffectMsg | undefined> => {
    try {
      await activeHandle.appendFile(`${JSON.stringify(frame)}\n`, 'utf8');
      return undefined;
    } catch (err) {
      return {
        type: 'runtime-issue',
        issue: {
          message: `Failed to stream profile: ${String(err)}`,
          level: 'error',
          source: 'command',
          atMs: Date.now(),
        },
      };
    }
  };
}

import type { Cmd } from '@flyingrobots/bijou-tui';
import { JEDIT_THEME_MODE, type JeditTheme } from '../ui/jedit-theme.js';

export const JEDIT_SETTING_ACTION = {
  CycleTheme: Symbol('jedit.settings.action.cycle-theme'),
  ToggleThemeMode: Symbol('jedit.settings.action.toggle-theme-mode'),
  ToggleFooter: Symbol('jedit.settings.action.toggle-footer'),
  ToggleMarkdownPreview: Symbol('jedit.settings.action.toggle-markdown-preview'),
  ToggleLocale: Symbol('jedit.settings.action.toggle-locale'),
} as const;

export type JeditSettingAction = typeof JEDIT_SETTING_ACTION[keyof typeof JEDIT_SETTING_ACTION];

export const JEDIT_SETTING_ROW_KIND = {
  Choice: Symbol('jedit.settings.row.choice'),
  Toggle: Symbol('jedit.settings.row.toggle'),
} as const;

export type JeditSettingRowKind = typeof JEDIT_SETTING_ROW_KIND[keyof typeof JEDIT_SETTING_ROW_KIND];

export interface JeditSettingsState {
  readonly jeditTheme: JeditTheme;
  readonly footerVisible: boolean;
  readonly markdownPreviewActive: boolean;
  readonly viewMode: 'source' | 'preview';
}

export interface JeditSettingsHostState {
  readonly settingsOpen: boolean;
  readonly settingsFocusIndex: number;
}

export interface JeditSettingsKeyMsg {
  readonly key: string;
}

export interface JeditSettingsHandlers<Model, Command> {
  cycleTheme(model: Model): [Model, Cmd<Command>[]];
  toggleThemeMode(model: Model): [Model, Cmd<Command>[]];
  toggleFooter(model: Model): [Model, Cmd<Command>[]];
  toggleMarkdownPreview(model: Model): [Model, Cmd<Command>[]];
  toggleLocale(model: Model): [Model, Cmd<Command>[]];
}

export interface JeditSettingsRow {
  readonly id: string;
  readonly section: string;
  readonly label: string;
  readonly description: string;
  readonly valueLabel: string;
  readonly kind: JeditSettingRowKind;
  readonly checked?: boolean;
  readonly action: JeditSettingAction;
}

const SETTINGS_SECTION_APPEARANCE = 'Appearance';
const SETTINGS_SECTION_EDITOR = 'Editor';
const ROW_ID_THEME = 'theme';
const ROW_ID_THEME_MODE = 'theme-mode';
const ROW_ID_FOOTER = 'footer';
const ROW_ID_MARKDOWN_PREVIEW = 'markdown-preview';
const ROW_ID_LOCALE = 'locale';
const VALUE_ON = 'On';
const VALUE_OFF = 'Off';
const VALUE_THEME_MODE_DARK = 'Dark';
const VALUE_THEME_MODE_LIGHT = 'Light';
const VALUE_SOURCE = 'Source';
const VALUE_PREVIEW = 'Preview';
const KEY_ESCAPE = 'escape';
const KEY_DOWN = 'down';
const KEY_UP = 'up';
const KEY_J = 'j';
const KEY_K = 'k';
const KEY_ENTER = 'enter';
const KEY_SPACE = ' ';
const KEY_SPACE_CANONICAL = 'space';
const FOCUS_STEP_FORWARD = 1;
const FOCUS_STEP_BACKWARD = -1;

export function jeditSettingsRows(state: JeditSettingsState & { readonly i18n: { readonly locale: string } }): readonly JeditSettingsRow[] {
  const rows: JeditSettingsRow[] = [
    {
      id: ROW_ID_LOCALE,
      section: SETTINGS_SECTION_APPEARANCE,
      label: 'Locale',
      description: 'Switch between English (en) and Mirror English (me) for RTL testing.',
      valueLabel: state.i18n.locale === 'en' ? 'English' : 'Mirror',
      kind: JEDIT_SETTING_ROW_KIND.Choice,
      action: JEDIT_SETTING_ACTION.ToggleLocale,
    },
    {
      id: ROW_ID_THEME,
      section: SETTINGS_SECTION_APPEARANCE,
      label: 'Theme',
      description: 'Switch between installed data-driven themes.',
      valueLabel: state.jeditTheme.name,
      kind: JEDIT_SETTING_ROW_KIND.Choice,
      action: JEDIT_SETTING_ACTION.CycleTheme,
    },
    {
      id: ROW_ID_THEME_MODE,
      section: SETTINGS_SECTION_APPEARANCE,
      label: 'Light/dark',
      description: 'Switch the current theme to its light or dark companion.',
      valueLabel: settingsThemeModeLabel(state.jeditTheme),
      kind: JEDIT_SETTING_ROW_KIND.Choice,
      action: JEDIT_SETTING_ACTION.ToggleThemeMode,
    },
    {
      id: ROW_ID_FOOTER,
      section: SETTINGS_SECTION_APPEARANCE,
      label: 'Footer',
      description: 'Show mode, focus, and command hints at the bottom edge.',
      valueLabel: state.footerVisible ? VALUE_ON : VALUE_OFF,
      kind: JEDIT_SETTING_ROW_KIND.Toggle,
      checked: state.footerVisible,
      action: JEDIT_SETTING_ACTION.ToggleFooter,
    },
  ];

  if (state.markdownPreviewActive) {
    rows.push({
      id: ROW_ID_MARKDOWN_PREVIEW,
      section: SETTINGS_SECTION_EDITOR,
      label: 'Markdown preview',
      description: 'Switch the active Markdown buffer between source and preview.',
      valueLabel: state.viewMode === 'preview' ? VALUE_PREVIEW : VALUE_SOURCE,
      kind: JEDIT_SETTING_ROW_KIND.Choice,
      action: JEDIT_SETTING_ACTION.ToggleMarkdownPreview,
    });
  }

  return rows;
}

function settingsThemeModeLabel(theme: JeditTheme): string {
  return theme.mode === JEDIT_THEME_MODE.Light ? VALUE_THEME_MODE_LIGHT : VALUE_THEME_MODE_DARK;
}

export function moveSettingsFocusIndex(index: number, delta: number, rowCount: number): number {
  return clampSettingsFocusIndex(index + delta, rowCount);
}

export function clampSettingsFocusIndex(index: number, rowCount: number): number {
  if (rowCount <= 0) {
    return 0;
  }
  return Math.max(0, Math.min(index, rowCount - 1));
}

export function toggleSettingsOpen<Model extends JeditSettingsHostState>(model: Model): Model {
  return {
    ...model,
    settingsOpen: !model.settingsOpen,
    settingsFocusIndex: 0,
  };
}

export function updateJeditSettingsFromKey<Model extends JeditSettingsHostState, Command>(
  msg: JeditSettingsKeyMsg,
  model: Model,
  rows: readonly JeditSettingsRow[],
  handlers: JeditSettingsHandlers<Model, Command>,
): [Model, Cmd<Command>[]] {
  if (msg.key === KEY_ESCAPE) {
    return [{ ...model, settingsOpen: false }, []];
  }
  if (msg.key === KEY_DOWN || msg.key === KEY_J) {
    return [moveHostFocus(model, FOCUS_STEP_FORWARD, rows.length), []];
  }
  if (msg.key === KEY_UP || msg.key === KEY_K) {
    return [moveHostFocus(model, FOCUS_STEP_BACKWARD, rows.length), []];
  }
  if (msg.key === KEY_ENTER || msg.key === KEY_SPACE || msg.key === KEY_SPACE_CANONICAL) {
    return activateSettingsRow(model, rows[clampSettingsFocusIndex(model.settingsFocusIndex, rows.length)]?.action, handlers);
  }
  return [model, []];
}

function moveHostFocus<Model extends JeditSettingsHostState>(model: Model, delta: number, rowCount: number): Model {
  return {
    ...model,
    settingsFocusIndex: moveSettingsFocusIndex(model.settingsFocusIndex, delta, rowCount),
  };
}

function activateSettingsRow<Model, Command>(
  model: Model,
  action: JeditSettingAction | undefined,
  handlers: JeditSettingsHandlers<Model, Command>,
): [Model, Cmd<Command>[]] {
  if (action === JEDIT_SETTING_ACTION.CycleTheme) {
    return handlers.cycleTheme(model);
  }
  if (action === JEDIT_SETTING_ACTION.ToggleThemeMode) {
    return handlers.toggleThemeMode(model);
  }
  if (action === JEDIT_SETTING_ACTION.ToggleFooter) {
    return handlers.toggleFooter(model);
  }
  if (action === JEDIT_SETTING_ACTION.ToggleMarkdownPreview) {
    return handlers.toggleMarkdownPreview(model);
  }
  if (action === JEDIT_SETTING_ACTION.ToggleLocale) {
    return handlers.toggleLocale(model);
  }
  return [model, []];
}

export class EditorCursor {
  readonly row: number;
  readonly col: number;

  constructor(row: number, col: number) {
    this.row = row;
    this.col = col;
    Object.freeze(this);
  }

  static origin(): EditorCursor {
    return new EditorCursor(0, 0);
  }

  moveTo(row: number, col: number): EditorCursor {
    return new EditorCursor(row, col);
  }

  clamp(lineCount: number, lineContent: string, isInsert: boolean): EditorCursor {
    const row = Math.max(0, Math.min(this.row, lineCount - 1));
    const maxCol = isInsert ? lineContent.length : Math.max(0, lineContent.length - 1);
    const col = Math.max(0, Math.min(this.col, maxCol));
    return new EditorCursor(row, col);
  }

  moveChar(direction: 'left' | 'right' | 'up' | 'down', lineCount: number, lineContent: string, isInsert: boolean, delta = 1): EditorCursor {
    switch (direction) {
      case 'left':
        if (isInsert && this.col < delta && this.row > 0) return this; // Handled by State
        return new EditorCursor(this.row, Math.max(0, this.col - delta));
      case 'right': {
        const maxCol = isInsert ? lineContent.length : Math.max(0, lineContent.length - 1);
        if (isInsert && this.col >= maxCol && this.row < lineCount - 1) return this; // Handled by State
        return new EditorCursor(this.row, Math.min(maxCol, this.col + delta));
      }
      case 'up':
      case 'down': {
        const nextRow = Math.max(0, Math.min(this.row + (direction === 'up' ? -delta : delta), lineCount - 1));
        return new EditorCursor(nextRow, this.col);
      }
    }
  }
}

import { EditorBuffer } from './editor-buffer.js';
import { EditorCursor } from './editor-cursor.js';
import type { EditorMotion, EditorMutation, RegisterState, RegisterKind } from './editor-state.js';
import { normalizeLines } from '../app/editor-lines.js';

export class EditorDocument {
  readonly buffer: EditorBuffer;
  readonly cursor: EditorCursor;

  constructor(buffer: EditorBuffer, cursor: EditorCursor) {
    this.buffer = buffer;
    this.cursor = cursor;
    Object.freeze(this);
  }

  with(patch: { buffer?: EditorBuffer; cursor?: EditorCursor }): EditorDocument {
    return new EditorDocument(patch.buffer ?? this.buffer, patch.cursor ?? this.cursor);
  }

  applyMotion(motion: EditorMotion, isInsert: boolean): EditorDocument {
    switch (motion.type) {
      case 'char': return this.applyCharMotion(motion.direction, isInsert, motion.delta ?? 1);
      case 'word': return this.applyWordMotion(motion.target);
      case 'line': return this.applyLineMotion(motion.target);
      case 'document': return this.applyDocumentMotion(motion.target);
    }
  }

  applyMutation(mutation: EditorMutation, register: RegisterState | undefined): { doc: EditorDocument; nextRegister?: RegisterState; nextMode?: 'normal' | 'insert' } {
    switch (mutation.type) {
      case 'insert': return { doc: this.insert(mutation.text) };
      case 'delete': return this.delete(mutation.target);
      case 'newline': return { doc: this.newline() };
      case 'backspace': return { doc: this.backspace() };
      case 'paste': return { doc: this.paste(mutation.placement, register) };
      case 'yank': return { doc: this, nextRegister: this.yank(mutation.target) };
    }
  }

  private applyCharMotion(direction: 'left' | 'right' | 'up' | 'down', isInsert: boolean, delta: number): EditorDocument {
    if (isInsert) {
      if (direction === 'left' && this.cursor.col < delta && this.cursor.row > 0) {
        const prevLine = this.buffer.lineAt(this.cursor.row - 1);
        return this.with({ cursor: new EditorCursor(this.cursor.row - 1, prevLine.length) });
      }
      if (direction === 'right' && this.cursor.col + delta > this.buffer.lineAt(this.cursor.row).length && this.cursor.row < this.buffer.lineCount() - 1) {
        return this.with({ cursor: new EditorCursor(this.cursor.row + 1, 0) });
      }
    }

    const nextCursor = this.cursor.moveChar(direction, this.buffer.lineCount(), this.buffer.lineAt(this.cursor.row), isInsert, delta);
    const clampedCursor = nextCursor.clamp(this.buffer.lineCount(), this.buffer.lineAt(nextCursor.row), isInsert);
    return this.with({ cursor: clampedCursor });
  }

  private applyWordMotion(target: 'start' | 'prev-start' | 'end'): EditorDocument {
    const currentIdx = this.buffer.textIndex(this.cursor.row, this.cursor.col);
    let targetIdx: number;
    switch (target) {
      case 'start': targetIdx = this.buffer.nextWordStart(currentIdx); break;
      case 'prev-start': targetIdx = this.buffer.prevWordStart(currentIdx); break;
      case 'end': targetIdx = this.buffer.wordEnd(currentIdx); break;
    }
    const pos = this.buffer.positionAt(targetIdx);
    return this.with({ cursor: new EditorCursor(pos.row, pos.col) });
  }

  private applyLineMotion(target: 'start' | 'end' | 'first-non-whitespace'): EditorDocument {
    const line = this.buffer.lineAt(this.cursor.row);
    let col: number;
    switch (target) {
      case 'start': col = 0; break;
      case 'end': col = line.length === 0 ? 0 : line.length - 1; break;
      case 'first-non-whitespace': {
        const match = line.match(/\S/);
        col = match == null ? 0 : match.index ?? 0;
        break;
      }
    }
    return this.with({ cursor: new EditorCursor(this.cursor.row, col) });
  }

  private applyDocumentMotion(target: 'top' | 'bottom'): EditorDocument {
    const row = target === 'top' ? 0 : this.buffer.lineCount() - 1;
    const line = this.buffer.lineAt(row);
    const col = Math.max(0, Math.min(this.cursor.col, line.length === 0 ? 0 : line.length - 1));
    return this.with({ cursor: new EditorCursor(row, col) });
  }

  private insert(text: string): EditorDocument {
    const line = this.buffer.lineAt(this.cursor.row);
    const nextLine = `${line.slice(0, this.cursor.col)}${text}${line.slice(this.cursor.col)}`;
    return this.with({
      buffer: this.buffer.replaceLine(this.cursor.row, nextLine),
      cursor: new EditorCursor(this.cursor.row, this.cursor.col + text.length),
    });
  }

  private delete(target: 'char' | 'line' | 'to-end'): { doc: EditorDocument; nextRegister?: RegisterState; nextMode?: 'normal' | 'insert' } {
    if (target === 'char') {
       const text = this.buffer.text();
       if (text.length === 0) return { doc: this };
       const start = this.buffer.textIndex(this.cursor.row, this.cursor.col);
       return this.deleteTextRange(start, start + 1, 'normal', 'char');
    }
    if (target === 'line') {
       const register: RegisterState = { kind: 'line', text: this.buffer.lineAt(this.cursor.row) };
       const nextBuffer = this.buffer.deleteLine(this.cursor.row);
       const nextRow = Math.min(this.cursor.row, nextBuffer.lineCount() - 1);
       const nextLine = nextBuffer.lineAt(nextRow);
       return {
         doc: this.with({ buffer: nextBuffer, cursor: new EditorCursor(nextRow, 0).clamp(nextBuffer.lineCount(), nextLine, false) }),
         nextRegister: register,
       };
    }
    // to-end
    const line = this.buffer.lineAt(this.cursor.row);
    const lineStart = this.buffer.lineStartTextIndex(this.cursor.row);
    return this.deleteTextRange(this.buffer.textIndex(this.cursor.row, this.cursor.col), lineStart + line.length, 'normal', 'char');
  }

  private deleteTextRange(start: number, end: number, mode: 'normal' | 'insert', registerKind: RegisterKind): { doc: EditorDocument; nextRegister?: RegisterState; nextMode?: 'normal' | 'insert' } {
    const text = this.buffer.text();
    const from = Math.max(0, Math.min(start, end));
    const to = Math.max(from, Math.min(text.length, Math.max(start, end)));
    if (from === to) return { doc: this, nextMode: mode };

    const nextText = `${text.slice(0, from)}${text.slice(to)}`;
    const nextLines = normalizeLines(nextText);
    const nextBuffer = new EditorBuffer(nextLines);
    const pos = nextBuffer.positionAt(from);
    const nextCursor = new EditorCursor(pos.row, pos.col).clamp(nextBuffer.lineCount(), nextBuffer.lineAt(pos.row), mode === 'insert');

    return {
      doc: new EditorDocument(nextBuffer, nextCursor),
      nextRegister: { kind: registerKind, text: text.slice(from, to) },
      nextMode: mode,
    };
  }

  private newline(): EditorDocument {
     const line = this.buffer.lineAt(this.cursor.row);
     const before = line.slice(0, this.cursor.col);
     const after = line.slice(this.cursor.col);
     return this.with({
       buffer: this.buffer.deleteLine(this.cursor.row).insertLine(this.cursor.row, before).insertLine(this.cursor.row + 1, after),
       cursor: new EditorCursor(this.cursor.row + 1, 0),
     });
  }

  private backspace(): EditorDocument {
    if (this.cursor.col > 0) {
      const line = this.buffer.lineAt(this.cursor.row);
      const nextLine = `${line.slice(0, this.cursor.col - 1)}${line.slice(this.cursor.col)}`;
      return this.with({
        buffer: this.buffer.replaceLine(this.cursor.row, nextLine),
        cursor: new EditorCursor(this.cursor.row, this.cursor.col - 1),
      });
    }
    if (this.cursor.row === 0) return this;
    const prevLine = this.buffer.lineAt(this.cursor.row - 1);
    const currentLine = this.buffer.lineAt(this.cursor.row);
    return this.with({
      buffer: this.buffer.deleteLine(this.cursor.row).replaceLine(this.cursor.row - 1, `${prevLine}${currentLine}`),
      cursor: new EditorCursor(this.cursor.row - 1, prevLine.length),
    });
  }

  private yank(target: 'line' | 'to-end'): RegisterState {
     if (target === 'line') {
       return { kind: 'line', text: this.buffer.lineAt(this.cursor.row) };
     }
     return { kind: 'char', text: this.buffer.lineAt(this.cursor.row).slice(this.cursor.col) };
  }

  private paste(placement: 'after' | 'before', register: RegisterState | undefined): EditorDocument {
    if (register == null || register.text.length === 0) return this;

    if (register.kind === 'line') {
      const index = placement === 'before' ? this.cursor.row : this.cursor.row + 1;
      const inserted = register.text.split('\n');
      let nextBuffer = this.buffer;
      for (let i = 0; i < inserted.length; i++) {
        nextBuffer = nextBuffer.insertLine(index + i, inserted[i] ?? '');
      }
      return this.with({
        buffer: nextBuffer,
        cursor: new EditorCursor(index, 0),
      });
    }

    const insertionIndex = placement === 'before'
      ? this.buffer.textIndex(this.cursor.row, this.cursor.col)
      : this.buffer.textIndex(this.cursor.row, this.cursor.col) + (this.buffer.lineAt(this.cursor.row).length === 0 ? 0 : 1);
    const text = this.buffer.text();
    const nextText = `${text.slice(0, insertionIndex)}${register.text}${text.slice(insertionIndex)}`;
    const nextLines = normalizeLines(nextText);
    const nextBuffer = new EditorBuffer(nextLines);
    const pos = nextBuffer.positionAt(insertionIndex + register.text.length - 1);
    return new EditorDocument(nextBuffer, new EditorCursor(pos.row, pos.col).clamp(nextBuffer.lineCount(), nextBuffer.lineAt(pos.row), false));
  }
}

export type WordCharClass = 'punct' | 'space' | 'word';

export function classifyWordChar(char: string | undefined): WordCharClass {
  if (char == null || /\s/.test(char)) {
    return 'space';
  }
  if (/[A-Za-z0-9_]/.test(char)) {
    return 'word';
  }
  return 'punct';
}

export function nextWordStartIndex(text: string, index: number, allowEnd = false): number {
  if (text.length === 0) {
    return 0;
  }

  let cursor = Math.max(0, Math.min(index, text.length - 1));
  if (classifyWordChar(text[cursor]) === 'space') {
    while (cursor < text.length && classifyWordChar(text[cursor]) === 'space') {
      cursor += 1;
    }
  } else {
    const currentClass = classifyWordChar(text[cursor]);
    while (cursor < text.length && classifyWordChar(text[cursor]) === currentClass) {
      cursor += 1;
    }
    while (cursor < text.length && classifyWordChar(text[cursor]) === 'space') {
      cursor += 1;
    }
  }

  if (allowEnd) {
    return Math.max(0, Math.min(text.length, cursor));
  }

  return Math.max(0, Math.min(text.length - 1, cursor));
}

export function previousWordStartIndex(text: string, index: number): number {
  if (text.length === 0) {
    return 0;
  }

  let cursor = Math.max(0, Math.min(index, text.length - 1));
  if (cursor === 0) {
    return 0;
  }

  cursor -= 1;
  while (cursor > 0 && classifyWordChar(text[cursor]) === 'space') {
    cursor -= 1;
  }

  const currentClass = classifyWordChar(text[cursor]);
  while (cursor > 0 && classifyWordChar(text[cursor - 1]) === currentClass) {
    cursor -= 1;
  }

  return cursor;
}

export function wordEndIndex(text: string, index: number): number {
  if (text.length === 0) {
    return 0;
  }

  let cursor = Math.max(0, Math.min(index, text.length - 1));
  while (cursor < text.length && classifyWordChar(text[cursor]) === 'space') {
    cursor += 1;
  }
  if (cursor >= text.length) {
    return text.length - 1;
  }

  const currentClass = classifyWordChar(text[cursor]);
  while (cursor < text.length - 1 && classifyWordChar(text[cursor + 1]) === currentClass) {
    cursor += 1;
  }

  return cursor;
}

import {
  replaceRange,
  type BufferRoot,
  type ReplaceReceipt,
  type TextFragment,
  type TextRange,
} from './text-edit-contract.js';

const TICK_ADMISSION_ERROR_INVALID_STATE = 1;
const FIRST_TICK_ID = 1;

export interface AdmittedTick {
  readonly id: number;
  readonly rootId: number;
}

export interface TickAdmissionState {
  readonly currentRoot: BufferRoot;
  readonly ticks: readonly AdmittedTick[];
}

export interface TickAdmissionReceipt {
  readonly tickId: number;
  readonly replaceReceipt: ReplaceReceipt;
}

export interface TickAdmissionResult {
  readonly nextState: TickAdmissionState;
  readonly receipt?: TickAdmissionReceipt;
}

export class TickAdmissionContractError extends Error {
  public readonly code: number;

  public constructor(code: number, message: string) {
    super(message);
    this.name = 'TickAdmissionContractError';
    this.code = code;
  }
}

export function createTickAdmissionState(
  currentRoot: BufferRoot,
  ticks: readonly AdmittedTick[] = [],
): TickAdmissionState {
  validateStateShape(currentRoot, ticks);

  return {
    currentRoot,
    ticks: [...ticks],
  };
}

export function admitReplaceRangeTick(
  state: TickAdmissionState,
  range: TextRange,
  fragment: TextFragment,
): TickAdmissionResult {
  validateStateShape(state.currentRoot, state.ticks);

  const replaceResult = replaceRange(state.currentRoot, range, fragment);
  if (replaceResult.receipt === undefined) {
    return { nextState: state };
  }

  const nextTick = {
    id: nextTickId(state.ticks),
    rootId: replaceResult.nextRoot.id,
  };

  return {
    nextState: {
      currentRoot: replaceResult.nextRoot,
      ticks: [...state.ticks, nextTick],
    },
    receipt: {
      tickId: nextTick.id,
      replaceReceipt: replaceResult.receipt,
    },
  };
}

function validateStateShape(currentRoot: BufferRoot, ticks: readonly AdmittedTick[]): void {
  if (!Number.isInteger(currentRoot.id) || currentRoot.id < FIRST_TICK_ID) {
    throw new TickAdmissionContractError(
      TICK_ADMISSION_ERROR_INVALID_STATE,
      'Tick admission requires a positive integer current root id.',
    );
  }

  let expectedTickId = FIRST_TICK_ID;
  let lastRootId: number | undefined;

  for (const tick of ticks) {
    if (!Number.isInteger(tick.id) || tick.id !== expectedTickId) {
      throw new TickAdmissionContractError(
        TICK_ADMISSION_ERROR_INVALID_STATE,
        'Tick admission history requires contiguous positive tick ids.',
      );
    }
    if (!Number.isInteger(tick.rootId) || tick.rootId < FIRST_TICK_ID) {
      throw new TickAdmissionContractError(
        TICK_ADMISSION_ERROR_INVALID_STATE,
        'Tick admission history requires positive integer root ids.',
      );
    }

    expectedTickId += 1;
    lastRootId = tick.rootId;
  }

  if (lastRootId !== undefined && currentRoot.id !== lastRootId) {
    throw new TickAdmissionContractError(
      TICK_ADMISSION_ERROR_INVALID_STATE,
      'Tick admission current root must match the last admitted tick root.',
    );
  }
}

function nextTickId(ticks: readonly AdmittedTick[]): number {
  const lastTick = ticks[ticks.length - 1];
  if (lastTick === undefined) {
    return FIRST_TICK_ID;
  }
  return lastTick.id + 1;
}

