const BUILT_IN_THEMES: readonly JeditTheme[] = [
  GRAPHITE_THEME,
  MORNING_THEME,
  MONOKAI_THEME,
  SOLARIZED_DARK_THEME,
  SOLARIZED_LIGHT_THEME,
  DRACULA_THEME,
  NORD_THEME,
  CATPPUCCIN_THEME,
];
const DEFAULT_THEME = GRAPHITE_THEME;
const GENERATED_COMPANION_CACHE = new Map<string, JeditTheme>();

export function availableJeditThemes(): readonly JeditTheme[] {
  return [...BUILT_IN_THEMES];
}

export function resolveInitialJeditTheme(themeName: string | undefined): JeditTheme {
  const match = BUILT_IN_THEMES.find((theme) => theme.name === themeName);
  return match ?? DEFAULT_THEME;
}

export function nextJeditTheme(current: JeditTheme): JeditTheme {
  const currentName = current.variantSource === JEDIT_THEME_VARIANT_SOURCE.Generated
    ? current.companionThemeName
    : current.name;
  const currentIndex = BUILT_IN_THEMES.findIndex((theme) => theme.name === currentName);
  const nextIndex = currentIndex < 0 ? 0 : (currentIndex + 1) % BUILT_IN_THEMES.length;
  return BUILT_IN_THEMES[nextIndex] ?? DEFAULT_THEME;
}

export function oppositeJeditTheme(theme: JeditTheme): JeditTheme {
  const authoredCompanion = theme.companionThemeName == null ? undefined : themeByName(theme.companionThemeName);
  if (authoredCompanion != null) {
    return authoredCompanion;
  }

  const targetMode = oppositeThemeMode(theme.mode);
  const cacheKey = `${theme.name}:${targetMode}`;
  const cached = GENERATED_COMPANION_CACHE.get(cacheKey);
  if (cached != null) {
    return cached;
  }

  const generated = definePaletteTheme(
    `${theme.familyName}-${targetMode}`,
    oppositePalette(paletteFromTheme(theme)),
    {
      mode: targetMode,
      familyName: theme.familyName,
      variantSource: JEDIT_THEME_VARIANT_SOURCE.Generated,
      companionThemeName: theme.name,
    },
  );
  GENERATED_COMPANION_CACHE.set(cacheKey, generated);
  return generated;
}

export function jeditThemeModeLabel(theme: JeditTheme): string {
  return theme.mode === JEDIT_THEME_MODE.Light ? THEME_MODE_LABEL_LIGHT : THEME_MODE_LABEL_DARK;
}

function definePaletteTheme(name: string, palette: ThemePalette, options: PaletteThemeOptions): JeditTheme {
  return defineJeditTheme(name, (draft) => {
    applyThemeTokens(draft, paletteVariables(draft, palette));
  }, {
    mode: options.mode,
    familyName: options.familyName,
    variantSource: options.variantSource,
    companionThemeName: options.companionThemeName,
  });
}

function paletteVariables(draft: JeditThemeDraft, palette: ThemePalette): ThemeVariables {
  return {
    ink: variableFromRgb(draft, VARIABLE_INK, palette.ink),
    muted: variableFromRgb(draft, VARIABLE_MUTED, palette.muted),
    accent: variableFromRgb(draft, VARIABLE_ACCENT, palette.accent),
    info: variableFromRgb(draft, VARIABLE_INFO, palette.info),
    warning: variableFromRgb(draft, VARIABLE_WARNING, palette.warning),
    success: variableFromRgb(draft, VARIABLE_SUCCESS, palette.success),
    surface: variableFromRgb(draft, VARIABLE_SURFACE, palette.surface),
    surfaceRaised: variableFromRgb(draft, VARIABLE_SURFACE_RAISED, palette.surfaceRaised),
    surfaceMuted: variableFromRgb(draft, VARIABLE_SURFACE_MUTED, palette.surfaceMuted),
  };
}

function variableFromRgb(draft: JeditThemeDraft, name: string, color: RgbTuple): ThemeColorVariable {
  return draft.variable(name, draft.rgb(color[0], color[1], color[2]));
}

function themeByName(themeName: string): JeditTheme | undefined {
  return BUILT_IN_THEMES.find((theme) => theme.name === themeName);
}

function oppositeThemeMode(mode: JeditThemeMode): JeditThemeMode {
  return mode === JEDIT_THEME_MODE.Dark ? JEDIT_THEME_MODE.Light : JEDIT_THEME_MODE.Dark;
}

function oppositePalette(palette: ThemePalette): ThemePalette {
  return {
    ink: invertColor(palette.ink),
    muted: invertColor(palette.muted),
    accent: invertColor(palette.accent),
    info: invertColor(palette.info),
    warning: invertColor(palette.warning),
    success: invertColor(palette.success),
    surface: invertColor(palette.surface),
    surfaceRaised: invertColor(palette.surfaceRaised),
    surfaceMuted: invertColor(palette.surfaceMuted),
  };
}

function paletteFromTheme(theme: JeditTheme): ThemePalette {
  return {
    ink: variableRgb(theme, VARIABLE_INK, [226, 231, 236]),
    muted: variableRgb(theme, VARIABLE_MUTED, [126, 137, 148]),
    accent: variableRgb(theme, VARIABLE_ACCENT, [216, 151, 255]),
    info: variableRgb(theme, VARIABLE_INFO, [101, 194, 255]),
    warning: variableRgb(theme, VARIABLE_WARNING, [245, 184, 92]),
    success: variableRgb(theme, VARIABLE_SUCCESS, [124, 213, 156]),
    surface: variableRgb(theme, VARIABLE_SURFACE, [14, 17, 22]),
    surfaceRaised: variableRgb(theme, VARIABLE_SURFACE_RAISED, [28, 32, 40]),
    surfaceMuted: variableRgb(theme, VARIABLE_SURFACE_MUTED, [22, 26, 33]),
  };
}

function variableRgb(theme: JeditTheme, name: string, fallback: RgbTuple): RgbTuple {
  return theme.variables.get(name)?.rgb ?? fallback;
}

function invertColor(color: RgbTuple): RgbTuple {
  return [
    COLOR_CHANNEL_MAX - color[0],
    COLOR_CHANNEL_MAX - color[1],
    COLOR_CHANNEL_MAX - color[2],
  ];
}

function applyThemeTokens(draft: JeditThemeDraft, variables: ThemeVariables): void {
  draft.surface.workspace.foregroundColor = variables.ink;
  draft.surface.workspace.backgroundColor = variables.surface;
  draft.surface.drawer.foregroundColor = variables.ink;
  draft.surface.drawer.backgroundColor = variables.surfaceMuted;
  draft.surface.footer.foregroundColor = variables.ink;
  draft.surface.footer.backgroundColor = variables.surfaceMuted;

  draft.cursor.normal.foregroundColor = variables.ink;
  draft.cursor.normal.backgroundColor = variables.accent;
  draft.cursor.normal.modifiers = [JEDIT_TEXT_MODIFIER.Inverse];
  draft.cursor.normal.spring = draft.spring({ mass: 1, stiffness: 180, damping: 24 });
  draft.cursor.insert.foregroundColor = variables.info;
  draft.cursor.insert.modifiers = [JEDIT_TEXT_MODIFIER.Underline];

  draft.chrome.activeEdge.char = ACTIVE_EDGE_CHAR;
  draft.chrome.activeEdge.foregroundColor = variables.accent;
  draft.chrome.titleLogo.foregroundColor = variables.accent.to(variables.info).easeInOut(6);
  draft.chrome.titleLogo.backgroundColor = variables.surface;
  draft.chrome.titleLogo.modifiers = [JEDIT_TEXT_MODIFIER.Bold];
  draft.chrome.titleLogo.gradient = draft.gradient(variables.accent, variables.info);
  draft.chrome.titleLogoShadow.foregroundColor = variables.muted;
  draft.chrome.titleLogoShadow.backgroundColor = variables.surface;
  draft.chrome.titleLogoShadow.modifiers = [JEDIT_TEXT_MODIFIER.Dim];
  draft.chrome.titleSceneNear.foregroundColor = variables.ink;
  draft.chrome.titleSceneNear.backgroundColor = variables.surface;
  draft.chrome.titleSceneFar.foregroundColor = variables.muted;
  draft.chrome.titleSceneFar.backgroundColor = variables.surface;

  draft.source.comment.foregroundColor = variables.muted;
  draft.source.comment.modifiers = [JEDIT_TEXT_MODIFIER.Dim, JEDIT_TEXT_MODIFIER.Italic];
  draft.source.function.foregroundColor = variables.accent;
  draft.source.keyword.foregroundColor = variables.accent.to(variables.info).easeIn(0.2);
  draft.source.keyword.modifiers = [JEDIT_TEXT_MODIFIER.Bold];
  draft.source.keyword.gradient = draft.gradient(variables.accent, variables.info);
  draft.source.keyword.spring = draft.spring({ mass: 1, stiffness: 160, damping: 20 });
  draft.source.number.foregroundColor = variables.info;
  draft.source.operator.foregroundColor = variables.warning;
  draft.source.property.foregroundColor = variables.ink;
  draft.source.punctuation.foregroundColor = variables.warning;
  draft.source.string.foregroundColor = variables.success;
  draft.source.type.foregroundColor = variables.accent;
  draft.source.variable.foregroundColor = variables.ink;

  draft.markdown.body.foregroundColor = variables.ink;
  draft.markdown.headingStrong.foregroundColor = variables.accent;
  draft.markdown.headingStrong.modifiers = [JEDIT_TEXT_MODIFIER.Bold];
  draft.markdown.headingStrong.gradient = draft.gradient(variables.accent, variables.info);
  draft.markdown.heading.foregroundColor = variables.info;
  draft.markdown.heading.modifiers = [JEDIT_TEXT_MODIFIER.Bold];
  draft.markdown.headingSoft.foregroundColor = variables.warning;
  draft.markdown.headingSoft.modifiers = [JEDIT_TEXT_MODIFIER.Bold];
  draft.markdown.listMarker.foregroundColor = variables.accent;
  draft.markdown.quoteMarker.foregroundColor = variables.muted;
  draft.markdown.quoteText.foregroundColor = variables.info;
  draft.markdown.code.foregroundColor = variables.ink;
  draft.markdown.code.backgroundColor = variables.surfaceRaised;
  draft.markdown.inlineCode.foregroundColor = variables.warning;
  draft.markdown.inlineCode.backgroundColor = variables.surfaceRaised;
  draft.markdown.rule.foregroundColor = variables.muted;
}

import { clipToWidth, stringToSurface, type Surface } from '@flyingrobots/bijou';
import { JEDIT_MARKDOWN_TOKEN, type JeditStyleToken, type JeditTheme } from './jedit-theme.js';

const FENCE_RE = /^\s*```/;
const HEADING_RE = /^\s*(#{1,6})\s+(.*)$/;
const UNORDERED_LIST_RE = /^\s*[-*]\s+(.*)$/;
const ORDERED_LIST_RE = /^\s*(\d+)[.)]\s+(.*)$/;
const QUOTE_RE = /^\s*>\s?(.*)$/;
const RULE_RE = /^\s*([-*_])(?:\s*\1){2,}\s*$/;
const INLINE_CODE_RE = /`([^`]+)`/g;
const LIST_BULLET = '• ';
const QUOTE_BULLET = '│ ';
const RULE_TEXT = '────────────────────────────────────────────────────────────────';

type PreviewLineKind = 'blank' | 'body' | 'heading-strong' | 'heading' | 'heading-soft' | 'list' | 'quote' | 'code' | 'rule';
type PreviewSegmentTone = 'body' | 'heading-strong' | 'heading' | 'heading-soft' | 'list-marker' | 'quote-marker' | 'quote-text' | 'code' | 'inline-code' | 'rule';

export interface MarkdownPreviewSegment {
  readonly text: string;
  readonly tone: PreviewSegmentTone;
}

export interface MarkdownPreviewLine {
  readonly kind: PreviewLineKind;
  readonly segments: readonly MarkdownPreviewSegment[];
}

export type MarkdownPreviewTheme = JeditTheme;

export function previewMarkdownLines(text: string): readonly MarkdownPreviewLine[] {
  const lines: MarkdownPreviewLine[] = [];
  let inCodeFence = false;

  for (const rawLine of text.replace(/\r\n/g, '\n').replace(/\r/g, '\n').split('\n')) {
    if (FENCE_RE.test(rawLine)) {
      inCodeFence = !inCodeFence;
      continue;
    }

    if (inCodeFence) {
      lines.push({
        kind: 'code',
        segments: [{ text: rawLine, tone: 'code' }],
      });
      continue;
    }

    const headingMatch = rawLine.match(HEADING_RE);
    if (headingMatch != null) {
      const headingMarks = headingMatch[1] ?? '#';
      const headingText = headingMatch[2] ?? '';
      lines.push({
        kind: headingKind(headingMarks.length),
        segments: inlineCodeSegments(headingText, headingTone(headingMarks.length)),
      });
      continue;
    }

    const unorderedListMatch = rawLine.match(UNORDERED_LIST_RE);
    if (unorderedListMatch != null) {
      const listText = unorderedListMatch[1] ?? '';
      lines.push({
        kind: 'list',
        segments: [
          { text: LIST_BULLET, tone: 'list-marker' },
          ...inlineCodeSegments(listText, 'body'),
        ],
      });
      continue;
    }

    const orderedListMatch = rawLine.match(ORDERED_LIST_RE);
    if (orderedListMatch != null) {
      const listIndex = orderedListMatch[1] ?? '1';
      const listText = orderedListMatch[2] ?? '';
      lines.push({
        kind: 'list',
        segments: [
          { text: `${listIndex}. `, tone: 'list-marker' },
          ...inlineCodeSegments(listText, 'body'),
        ],
      });
      continue;
    }

    const quoteMatch = rawLine.match(QUOTE_RE);
    if (quoteMatch != null) {
      const quoteText = quoteMatch[1] ?? '';
      lines.push({
        kind: 'quote',
        segments: [
          { text: QUOTE_BULLET, tone: 'quote-marker' },
          ...inlineCodeSegments(quoteText, 'quote-text'),
        ],
      });
      continue;
    }

    if (RULE_RE.test(rawLine)) {
      lines.push({
        kind: 'rule',
        segments: [{ text: RULE_TEXT, tone: 'rule' }],
      });
      continue;
    }

    if (rawLine.trim().length === 0) {
      lines.push({ kind: 'blank', segments: [] });
      continue;
    }

    lines.push({
      kind: 'body',
      segments: inlineCodeSegments(rawLine, 'body'),
    });
  }

  return lines;
}

export function paintMarkdownPreview(
  surface: Surface,
  text: string,
  scrollRow: number,
  x: number,
  y: number,
  width: number,
  height: number,
  theme: MarkdownPreviewTheme,
) {
  const lines = previewMarkdownLines(text);
  for (let row = 0; row < height; row += 1) {
    const line = lines[scrollRow + row];
    if (line == null) {
      continue;
    }

    paintPreviewBackground(surface, line, x, y + row, width, theme);
    paintPreviewSegments(surface, line.segments, x, y + row, width, theme);
  }
}

function paintPreviewBackground(
  surface: Surface,
  line: MarkdownPreviewLine,
  x: number,
  y: number,
  width: number,
  theme: MarkdownPreviewTheme,
) {
  if (line.kind !== 'code') {
    return;
  }

  const token = codeLineToken(theme);
  for (let column = 0; column < width; column += 1) {
    const cell = surface.get(x + column, y);
    surface.set(x + column, y, {
      ...cell,
      char: cell.char.length > 0 ? cell.char : ' ',
      bg: token.bg,
      bgRGB: token.bgRGB,
      empty: false,
    });
  }
}

function paintPreviewSegments(
  surface: Surface,
  segments: readonly MarkdownPreviewSegment[],
  x: number,
  y: number,
  width: number,
  theme: MarkdownPreviewTheme,
) {
  let cursor = x;
  const end = x + width;

  for (const segment of segments) {
    if (cursor >= end) {
      return;
    }

    const clipped = clipToWidth(segment.text, end - cursor);
    if (clipped.length === 0) {
      continue;
    }

    const segmentSurface = stringToSurface(clipped, [...clipped].length, 1);
    applyToken(segmentSurface, tokenForTone(theme, segment.tone));
    surface.blit(segmentSurface, cursor, y);
    cursor += [...clipped].length;
  }
}

function applyToken(surface: Surface, token: JeditStyleToken) {
  for (let row = 0; row < surface.height; row += 1) {
    for (let column = 0; column < surface.width; column += 1) {
      const cell = surface.get(column, row);
      if (cell.empty) {
        continue;
      }
      surface.set(column, row, {
        ...cell,
        fg: token.fg,
        fgRGB: token.fgRGB,
        bg: token.bg,
        bgRGB: token.bgRGB,
        modifiers: token.modifiers == null ? undefined : [...token.modifiers],
        empty: false,
      });
    }
  }
}

function tokenForTone(theme: MarkdownPreviewTheme, tone: PreviewSegmentTone): JeditStyleToken {
  if (tone === 'heading-strong') {
    return markdownToken(theme, JEDIT_MARKDOWN_TOKEN.HeadingStrong);
  }
  if (tone === 'heading') {
    return markdownToken(theme, JEDIT_MARKDOWN_TOKEN.Heading);
  }
  if (tone === 'heading-soft') {
    return markdownToken(theme, JEDIT_MARKDOWN_TOKEN.HeadingSoft);
  }
  if (tone === 'list-marker') {
    return markdownToken(theme, JEDIT_MARKDOWN_TOKEN.ListMarker);
  }
  if (tone === 'quote-marker') {
    return markdownToken(theme, JEDIT_MARKDOWN_TOKEN.QuoteMarker);
  }
  if (tone === 'quote-text') {
    return markdownToken(theme, JEDIT_MARKDOWN_TOKEN.QuoteText);
  }
  if (tone === 'code') {
    return markdownToken(theme, JEDIT_MARKDOWN_TOKEN.Code);
  }
  if (tone === 'inline-code') {
    return markdownToken(theme, JEDIT_MARKDOWN_TOKEN.InlineCode);
  }
  if (tone === 'rule') {
    return markdownToken(theme, JEDIT_MARKDOWN_TOKEN.Rule);
  }
  return markdownToken(theme, JEDIT_MARKDOWN_TOKEN.Body);
}

function codeLineToken(theme: MarkdownPreviewTheme): JeditStyleToken {
  return markdownToken(theme, JEDIT_MARKDOWN_TOKEN.Code);
}

function markdownToken(theme: MarkdownPreviewTheme, token: typeof JEDIT_MARKDOWN_TOKEN[keyof typeof JEDIT_MARKDOWN_TOKEN]): JeditStyleToken {
  return theme.markdown.get(token) ?? theme.surface.workspace;
}

function headingKind(depth: number): PreviewLineKind {
  if (depth <= 1) {
    return 'heading-strong';
  }
  if (depth === 2) {
    return 'heading';
  }
  return 'heading-soft';
}

function headingTone(depth: number): PreviewSegmentTone {
  if (depth <= 1) {
    return 'heading-strong';
  }
  if (depth === 2) {
    return 'heading';
  }
  return 'heading-soft';
}

function inlineCodeSegments(text: string, baseTone: PreviewSegmentTone): readonly MarkdownPreviewSegment[] {
  const segments: MarkdownPreviewSegment[] = [];
  let cursor = 0;

  for (const match of text.matchAll(INLINE_CODE_RE)) {
    const fullMatch = match[0];
    const codeText = match[1];
    const matchIndex = match.index ?? -1;
    if (matchIndex < 0 || codeText == null) {
      continue;
    }

    if (matchIndex > cursor) {
      segments.push({ text: text.slice(cursor, matchIndex), tone: baseTone });
    }

    segments.push({ text: codeText, tone: 'inline-code' });
    cursor = matchIndex + fullMatch.length;
  }

  if (cursor < text.length) {
    segments.push({ text: text.slice(cursor), tone: baseTone });
  }

  if (segments.length === 0) {
    return [{ text, tone: baseTone }];
  }

  return segments;
}

import { createSurface, stringToSurface, type Surface } from '@flyingrobots/bijou';
import type { JeditSettingsRow } from '../app/settings-session.js';
import { JEDIT_SETTING_ROW_KIND } from '../app/settings-session.js';
import { JEDIT_SETTINGS_TOGGLE_LABEL } from '../app/keybindings.js';
import { JEDIT_MARKDOWN_TOKEN, JEDIT_SOURCE_TOKEN, type JeditStyleToken, type JeditTheme } from './jedit-theme.js';
import { fitLine } from './workspace-render.js';

const SETTINGS_DRAWER_MIN_WIDTH = 28;
const SETTINGS_DRAWER_MAX_WIDTH = 42;
const SETTINGS_DRAWER_WIDTH_RATIO = 0.3;
const SETTINGS_HEADER_ROW = 1;
const SETTINGS_HINT_ROW = 2;
const SETTINGS_FIRST_ROW = 4;
const SETTINGS_LEFT_PAD = 2;
const SETTINGS_ROW_GAP = 1;
const SETTINGS_ROW_HEIGHT = 2;
const SETTINGS_SELECTED_MARK = '›';
const SETTINGS_UNSELECTED_MARK = ' ';
const SETTINGS_CHOICE_MARK = '↻';
const SETTINGS_CHECKED_MARK = '☑';
const SETTINGS_UNCHECKED_MARK = '☐';
const SETTINGS_CLOSE_HINT = `${JEDIT_SETTINGS_TOGGLE_LABEL.toUpperCase()}/Esc close`;
const SETTINGS_TITLE = 'Settings';

export interface RenderSettingsDrawerOptions {
  readonly rows: readonly JeditSettingsRow[];
  readonly selectedIndex: number;
  readonly theme: JeditTheme;
  readonly width: number;
  readonly height: number;
}

export function resolveSettingsDrawerWidth(columns: number): number {
  const boundedColumns = Math.max(SETTINGS_DRAWER_MIN_WIDTH, columns);
  return Math.min(
    Math.max(SETTINGS_DRAWER_MIN_WIDTH, Math.floor(boundedColumns * SETTINGS_DRAWER_WIDTH_RATIO)),
    Math.max(SETTINGS_DRAWER_MIN_WIDTH, boundedColumns - SETTINGS_LEFT_PAD),
    SETTINGS_DRAWER_MAX_WIDTH,
  );
}

export function renderSettingsDrawer(options: RenderSettingsDrawerOptions): Surface {
  const surface = createSurface(options.width, options.height);
  fillSurface(surface, options.theme.surface.drawer);
  paintText(surface, SETTINGS_TITLE, SETTINGS_LEFT_PAD, SETTINGS_HEADER_ROW, options.theme.markdown.get(JEDIT_MARKDOWN_TOKEN.Heading) ?? options.theme.surface.drawer);
  paintText(surface, SETTINGS_CLOSE_HINT, SETTINGS_LEFT_PAD, SETTINGS_HINT_ROW, options.theme.source.get(JEDIT_SOURCE_TOKEN.Comment) ?? options.theme.surface.drawer);

  let y = SETTINGS_FIRST_ROW;
  let section = '';
  for (let index = 0; index < options.rows.length && y < options.height; index += 1) {
    const row = options.rows[index];
    if (row == null) {
      continue;
    }
    if (row.section !== section) {
      section = row.section;
      paintText(surface, section, SETTINGS_LEFT_PAD, y, options.theme.markdown.get(JEDIT_MARKDOWN_TOKEN.HeadingSoft) ?? options.theme.surface.drawer);
      y += SETTINGS_ROW_GAP;
    }
    paintSettingsRow(surface, row, index === options.selectedIndex, SETTINGS_LEFT_PAD, y, options.theme);
    y += SETTINGS_ROW_HEIGHT;
  }
  return surface;
}

function paintSettingsRow(surface: Surface, row: JeditSettingsRow, selected: boolean, x: number, y: number, theme: JeditTheme): void {
  if (y >= surface.height) {
    return;
  }
  const label = fitLine(`${selected ? SETTINGS_SELECTED_MARK : SETTINGS_UNSELECTED_MARK} ${rowMark(row)} ${row.label} ${row.valueLabel}`, Math.max(1, surface.width - x));
  const labelToken = selected ? theme.cursor.normal : theme.surface.drawer;
  paintText(surface, label, x, y, labelToken);

  if (y + 1 < surface.height) {
    const descriptionToken = theme.source.get(JEDIT_SOURCE_TOKEN.Comment) ?? theme.surface.drawer;
    paintText(surface, `  ${row.description}`, x, y + 1, descriptionToken);
  }
}

function rowMark(row: JeditSettingsRow): string {
  if (row.kind === JEDIT_SETTING_ROW_KIND.Choice) {
    return SETTINGS_CHOICE_MARK;
  }
  return row.checked === true ? SETTINGS_CHECKED_MARK : SETTINGS_UNCHECKED_MARK;
}

function paintText(surface: Surface, text: string, x: number, y: number, token: JeditStyleToken): void {
  if (y < 0 || y >= surface.height || x >= surface.width) {
    return;
  }
  const width = Math.max(1, surface.width - x);
  const line = stringToSurface(fitLine(text, width), width, 1);
  applyToken(line, token);
  surface.blit(line, x, y);
}

function fillSurface(surface: Surface, token: JeditStyleToken): void {
  surface.fill({
    char: ' ',
    fg: token.fg,
    fgRGB: token.fgRGB,
    bg: token.bg,
    bgRGB: token.bgRGB,
    empty: false,
  });
}

function applyToken(surface: Surface, token: JeditStyleToken): void {
  for (let y = 0; y < surface.height; y += 1) {
    for (let x = 0; x < surface.width; x += 1) {
      const cell = surface.get(x, y);
      surface.set(x, y, {
        ...cell,
        fg: token.fg,
        fgRGB: token.fgRGB,
        bg: token.bg,
        bgRGB: token.bgRGB,
        modifiers: token.modifiers == null ? undefined : [...token.modifiers],
        empty: false,
      });
    }
  }
}

import type { Cell, Surface } from '@flyingrobots/bijou';
import type { SourceHighlightReading, SourceHighlightRole, SourceHighlightSpan } from '../ports/source-highlighter.js';
import type { JeditStyleToken, JeditTheme } from './jedit-theme.js';
import type { SourceWindowReading } from './source-window.js';

const ZERO_INDEX = 0;
const MIN_RENDER_SIZE = 1;
const SPACE_CHAR = ' ';

type CellStyle = Pick<Cell, 'fg' | 'bg' | 'fgRGB' | 'bgRGB' | 'modifiers'>;

export interface PaintHighlightedSourceWindowOptions {
  readonly x: number;
  readonly y: number;
  readonly scrollCol: number;
  readonly width: number;
  readonly height: number;
  readonly theme: JeditTheme;
}

export function paintHighlightedSourceWindow(
  surface: Surface,
  reading: SourceWindowReading,
  highlight: SourceHighlightReading | undefined,
  options: PaintHighlightedSourceWindowOptions,
): void {
  const safeScrollCol = Math.max(ZERO_INDEX, options.scrollCol);
  const safeWidth = Math.max(MIN_RENDER_SIZE, options.width);
  const safeHeight = Math.max(MIN_RENDER_SIZE, options.height);

  for (let row = ZERO_INDEX; row < safeHeight; row += 1) {
    const sourceLine = reading.lines[row];
    const sourceText = sourceLine?.text ?? '';
    const sourceRow = sourceLine?.lineNumber ?? reading.startLine + row;

    for (let col = ZERO_INDEX; col < safeWidth; col += 1) {
      const sourceCol = safeScrollCol + col;
      const char = sourceText[sourceCol] ?? SPACE_CHAR;
      const style = styleAt(highlight?.spans ?? [], sourceRow, sourceCol, options.theme);
      surface.set(options.x + col, options.y + row, {
        char,
        ...style,
        empty: false,
      });
    }
  }
}

function styleAt(
  spans: readonly SourceHighlightSpan[],
  row: number,
  column: number,
  theme: JeditTheme,
): CellStyle {
  for (const span of spans) {
    if (spanContainsCell(span, row, column)) {
      return styleForRole(span.role, theme);
    }
  }
  return {};
}

function spanContainsCell(span: SourceHighlightSpan, row: number, column: number): boolean {
  if (row < span.range.start.row || row > span.range.end.row) {
    return false;
  }
  if (row === span.range.start.row && column < span.range.start.column) {
    return false;
  }
  if (row === span.range.end.row && column >= span.range.end.column) {
    return false;
  }
  return true;
}

function styleForRole(role: SourceHighlightRole, theme: JeditTheme): CellStyle {
  const sourceToken = theme.sourceRoleMap.get(role);
  if (sourceToken == null) {
    return {};
  }
  const token = theme.source.get(sourceToken);
  return token == null ? {} : tokenStyle(token);
}

function tokenStyle(token: JeditStyleToken): CellStyle {
  return {
    fg: token.fg,
    bg: token.bg,
    fgRGB: token.fgRGB,
    bgRGB: token.bgRGB,
    modifiers: token.modifiers == null ? undefined : [...token.modifiers],
  };
}

import type { Cell, Surface } from '@flyingrobots/bijou';
import type { SourceHighlightReading } from '../ports/source-highlighter.js';
import type { JeditStyleToken, JeditTheme } from './jedit-theme.js';
import { createSourceWindowReadingFromLines } from './source-window.js';
import { paintHighlightedSourceWindow } from './source-highlight.js';

const NORMAL_MODE = 'normal';
const INSERT_MODE = 'insert';

export type SourceViewerMode = typeof NORMAL_MODE | typeof INSERT_MODE;

export interface SourceViewerEditor {
  readonly lines: readonly string[];
  readonly cursorRow: number;
  readonly cursorCol: number;
  readonly scrollRow: number;
  readonly scrollCol: number;
  readonly mode: SourceViewerMode;
}

export interface SourceViewerViewport {
  readonly width: number;
  readonly height: number;
}

export interface SourceViewerOptions {
  readonly viewport: SourceViewerViewport;
  readonly leftPad: number;
  readonly topPad: number;
  readonly theme: JeditTheme;
}

export function renderSourceViewer(
  surface: Surface,
  editor: SourceViewerEditor,
  highlight: SourceHighlightReading | undefined,
  options: SourceViewerOptions,
): Surface {
  const sourceWindow = createSourceWindowReadingFromLines({
    lines: editor.lines,
    startLine: editor.scrollRow,
    lineCount: options.viewport.height,
  });
  paintHighlightedSourceWindow(surface, sourceWindow, highlight, {
    x: options.leftPad,
    y: options.topPad,
    scrollCol: editor.scrollCol,
    width: options.viewport.width,
    height: options.viewport.height,
    theme: options.theme,
  });

  const cursor = cursorDisplayPosition(editor);
  const cursorY = options.topPad + (cursor.row - editor.scrollRow);
  const cursorX = options.leftPad + (cursor.col - editor.scrollCol);
  if (
    cursorY >= options.topPad
    && cursorY < options.topPad + options.viewport.height
    && cursorX >= options.leftPad
    && cursorX < options.leftPad + options.viewport.width
  ) {
    const cell = surface.get(cursorX, cursorY);
    const token = editor.mode === NORMAL_MODE ? options.theme.cursor.normal : options.theme.cursor.insert;
    surface.set(cursorX, cursorY, {
      ...cell,
      char: cell.char.length > 0 ? cell.char : cursorFallbackChar(editor.mode),
      ...cellStyle(token),
      empty: false,
    });
  }

  return surface;
}

function cursorDisplayPosition(editor: SourceViewerEditor): { readonly row: number; readonly col: number } {
  if (editor.mode === INSERT_MODE) {
    return {
      row: editor.cursorRow,
      col: editor.cursorCol,
    };
  }

  const line = editor.lines[editor.cursorRow] ?? '';
  return {
    row: editor.cursorRow,
    col: line.length === 0 ? 0 : Math.min(editor.cursorCol, line.length - 1),
  };
}

function cursorFallbackChar(mode: SourceViewerMode): string {
  return mode === NORMAL_MODE ? ' ' : '│';
}

function cellStyle(token: JeditStyleToken): Pick<Cell, 'fg' | 'bg' | 'fgRGB' | 'bgRGB' | 'modifiers'> {
  return {
    fg: token.fg,
    bg: token.bg,
    fgRGB: token.fgRGB,
    bgRGB: token.bgRGB,
    modifiers: token.modifiers == null ? undefined : [...token.modifiers],
  };
}

import {
  JEDIT_COLOR_EFFECT,
  JEDIT_EASING,
  JEDIT_MARKDOWN_TOKEN,
  JEDIT_SOURCE_TOKEN,
  JEDIT_THEME_MODE,
  JEDIT_THEME_VARIANT_SOURCE,
  JEDIT_TEXT_MODIFIER,
  type JeditColorEffect,
  type JeditColorStop,
  type JeditEasing,
  type JeditGradient,
  type JeditGradientStop,
  type JeditMarkdownToken,
  type JeditSourceToken,
  type JeditSpring,
  type JeditStyleToken,
  type JeditTextModifier,
  type JeditTheme,
  type JeditThemeMode,
  type JeditThemeVariantSource,
} from './jedit-theme.js';
import { SOURCE_HIGHLIGHT_ROLE } from '../ports/source-highlighter.js';
import { DuplicateThemeVariableError } from '../domain/errors.js';

const COLOR_CHANNEL_MIN = 0;
const COLOR_CHANNEL_MAX = 255;
const HEX_RADIX = 16;
const HEX_PAIR_WIDTH = 2;
const PERCENT_START = 0;
const PERCENT_END = 1;
const MODE_LUMINANCE_THRESHOLD = 128;
const LUMINANCE_RED_WEIGHT = 0.2126;
const LUMINANCE_GREEN_WEIGHT = 0.7152;
const LUMINANCE_BLUE_WEIGHT = 0.0722;

type ThemeColorPaint = RgbColor | ThemeColorVariable | ThemeColorTransition;

export class RgbColor implements JeditColorStop {
  readonly red: number;
  readonly green: number;
  readonly blue: number;
  readonly hex: string;
  readonly rgb: readonly [number, number, number];

  constructor(red: number, green: number, blue: number) {
    this.red = clampChannel(red);
    this.green = clampChannel(green);
    this.blue = clampChannel(blue);
    this.rgb = [this.red, this.green, this.blue];
    this.hex = rgbHex(this.red, this.green, this.blue);
  }

  to(next: RgbColor | ThemeColorVariable): ThemeColorTransitionDraft {
    return new ThemeColorTransitionDraft(this, next);
  }

  toTokenValue(): JeditStyleToken {
    return styleTokenFromDraft({ foregroundColor: this });
  }
}

export class ThemeColorVariable implements JeditColorStop {
  readonly red: number;
  readonly green: number;
  readonly blue: number;
  readonly hex: string;
  readonly rgb: readonly [number, number, number];
  readonly variableName: string;

  constructor(variableName: string, color: RgbColor) {
    this.variableName = variableName;
    this.red = color.red;
    this.green = color.green;
    this.blue = color.blue;
    this.rgb = color.rgb;
    this.hex = color.hex;
  }

  to(next: RgbColor | ThemeColorVariable): ThemeColorTransitionDraft {
    return new ThemeColorTransitionDraft(this, next);
  }

  toTokenValue(): JeditStyleToken {
    return styleTokenFromDraft({ foregroundColor: this });
  }
}

export class ThemeColorTransition {
  readonly kind = JEDIT_COLOR_EFFECT.Transition;
  readonly from: JeditColorStop;
  readonly to: JeditColorStop;
  readonly easing: JeditEasing;
  readonly durationSeconds: number;

  constructor(from: JeditColorStop, to: JeditColorStop, easing: JeditEasing, durationSeconds: number) {
    this.from = from;
    this.to = to;
    this.easing = easing;
    this.durationSeconds = durationSeconds;
  }
}

export class ThemeColorTransitionDraft {
  private readonly from: JeditColorStop;
  private readonly toColor: JeditColorStop;

  constructor(from: JeditColorStop, toColor: JeditColorStop) {
    this.from = from;
    this.toColor = toColor;
  }

  linear(durationSeconds: number): ThemeColorTransition {
    return this.transition(JEDIT_EASING.Linear, durationSeconds);
  }

  easeIn(durationSeconds: number): ThemeColorTransition {
    return this.transition(JEDIT_EASING.EaseIn, durationSeconds);
  }

  easeOut(durationSeconds: number): ThemeColorTransition {
    return this.transition(JEDIT_EASING.EaseOut, durationSeconds);
  }

  easeInOut(durationSeconds: number): ThemeColorTransition {
    return this.transition(JEDIT_EASING.EaseInOut, durationSeconds);
  }

  private transition(easing: JeditEasing, durationSeconds: number): ThemeColorTransition {
    return new ThemeColorTransition(this.from, this.toColor, easing, Math.max(0, durationSeconds));
  }
}

export interface JeditStyleDraft {
  char?: string;
  foregroundColor?: ThemeColorPaint;
  backgroundColor?: ThemeColorPaint;
  modifiers?: readonly JeditTextModifier[];
  gradient?: JeditGradient;
  spring?: JeditSpring;
}

export interface JeditSourceStyleDrafts {
  readonly comment: JeditStyleDraft;
  readonly function: JeditStyleDraft;
  readonly keyword: JeditStyleDraft;
  readonly number: JeditStyleDraft;
  readonly operator: JeditStyleDraft;
  readonly property: JeditStyleDraft;
  readonly punctuation: JeditStyleDraft;
  readonly string: JeditStyleDraft;
  readonly type: JeditStyleDraft;
  readonly variable: JeditStyleDraft;
}

export interface JeditMarkdownStyleDrafts {
  readonly body: JeditStyleDraft;
  readonly headingStrong: JeditStyleDraft;
  readonly heading: JeditStyleDraft;
  readonly headingSoft: JeditStyleDraft;
  readonly listMarker: JeditStyleDraft;
  readonly quoteMarker: JeditStyleDraft;
  readonly quoteText: JeditStyleDraft;
  readonly code: JeditStyleDraft;
  readonly inlineCode: JeditStyleDraft;
  readonly rule: JeditStyleDraft;
}

export interface JeditSurfaceStyleDrafts {
  readonly workspace: JeditStyleDraft;
  readonly drawer: JeditStyleDraft;
  readonly footer: JeditStyleDraft;
}

export interface JeditCursorStyleDrafts {
  readonly normal: JeditStyleDraft;
  readonly insert: JeditStyleDraft;
}

export interface JeditChromeStyleDrafts {
  readonly activeEdge: JeditStyleDraft;
  readonly titleLogo: JeditStyleDraft;
  readonly titleLogoShadow: JeditStyleDraft;
  readonly titleSceneNear: JeditStyleDraft;
  readonly titleSceneFar: JeditStyleDraft;
}

export interface JeditThemeDraft {
  readonly style: typeof JEDIT_TEXT_MODIFIER;
  readonly source: JeditSourceStyleDrafts;
  readonly markdown: JeditMarkdownStyleDrafts;
  readonly surface: JeditSurfaceStyleDrafts;
  readonly cursor: JeditCursorStyleDrafts;
  readonly chrome: JeditChromeStyleDrafts;
  rgb(red: number, green: number, blue: number): RgbColor;
  variable(name: string, color: RgbColor): ThemeColorVariable;
  gradient(first: RgbColor | ThemeColorVariable, second: RgbColor | ThemeColorVariable): JeditGradient;
  spring(input: JeditSpring): JeditSpring;
}

export interface JeditThemeDefinitionOptions {
  readonly mode?: JeditThemeMode;
  readonly familyName?: string;
  readonly variantSource?: JeditThemeVariantSource;
  readonly companionThemeName?: string;
}

export function rgb(red: number, green: number, blue: number): RgbColor {
  return new RgbColor(red, green, blue);
}

export function defineJeditTheme(
  name: string,
  build: (draft: JeditThemeDraft) => void,
  options: JeditThemeDefinitionOptions = {},
): JeditTheme {
  const variables = new Map<string, JeditColorStop>();
  const draft = createThemeDraft(variables);
  build(draft);
  const surface = {
    workspace: styleTokenFromDraft(draft.surface.workspace),
    drawer: styleTokenFromDraft(draft.surface.drawer),
    footer: styleTokenFromDraft(draft.surface.footer),
  };

  return {
    name,
    mode: options.mode ?? inferThemeMode(surface.workspace),
    familyName: options.familyName ?? name,
    variantSource: options.variantSource ?? JEDIT_THEME_VARIANT_SOURCE.Authored,
    companionThemeName: options.companionThemeName,
    variables,
    source: buildSourceTokens(draft.source),
    sourceRoleMap: new Map([
      [SOURCE_HIGHLIGHT_ROLE.Comment, JEDIT_SOURCE_TOKEN.Comment],
      [SOURCE_HIGHLIGHT_ROLE.Function, JEDIT_SOURCE_TOKEN.Function],
      [SOURCE_HIGHLIGHT_ROLE.Keyword, JEDIT_SOURCE_TOKEN.Keyword],
      [SOURCE_HIGHLIGHT_ROLE.Number, JEDIT_SOURCE_TOKEN.Number],
      [SOURCE_HIGHLIGHT_ROLE.Operator, JEDIT_SOURCE_TOKEN.Operator],
      [SOURCE_HIGHLIGHT_ROLE.Property, JEDIT_SOURCE_TOKEN.Property],
      [SOURCE_HIGHLIGHT_ROLE.Punctuation, JEDIT_SOURCE_TOKEN.Punctuation],
      [SOURCE_HIGHLIGHT_ROLE.String, JEDIT_SOURCE_TOKEN.String],
      [SOURCE_HIGHLIGHT_ROLE.Type, JEDIT_SOURCE_TOKEN.Type],
      [SOURCE_HIGHLIGHT_ROLE.Variable, JEDIT_SOURCE_TOKEN.Variable],
    ]),
    markdown: buildMarkdownTokens(draft.markdown),
    surface,
    cursor: {
      normal: styleTokenFromDraft(draft.cursor.normal),
      insert: styleTokenFromDraft(draft.cursor.insert),
    },
    chrome: {
      activeEdge: styleTokenFromDraft(draft.chrome.activeEdge),
      titleLogo: styleTokenFromDraft(draft.chrome.titleLogo),
      titleLogoShadow: styleTokenFromDraft(draft.chrome.titleLogoShadow),
      titleSceneNear: styleTokenFromDraft(draft.chrome.titleSceneNear),
      titleSceneFar: styleTokenFromDraft(draft.chrome.titleSceneFar),
    },
  };
}

function createThemeDraft(variables: Map<string, JeditColorStop>): JeditThemeDraft {
  return {
    style: JEDIT_TEXT_MODIFIER,
    source: createSourceDrafts(),
    markdown: createMarkdownDrafts(),
    surface: { workspace: {}, drawer: {}, footer: {} },
    cursor: { normal: {}, insert: {} },
    chrome: {
      activeEdge: {},
      titleLogo: {},
      titleLogoShadow: {},
      titleSceneNear: {},
      titleSceneFar: {},
    },
    rgb,
    variable(name: string, color: RgbColor): ThemeColorVariable {
      if (variables.has(name)) {
        throw new DuplicateThemeVariableError(`Duplicate theme variable name: ${name}`);
      }
      const variable = new ThemeColorVariable(name, color);
      variables.set(name, variable);
      return variable;
    },
    gradient(first: RgbColor | ThemeColorVariable, second: RgbColor | ThemeColorVariable): JeditGradient {
      return {
        stops: [
          gradientStop(first, PERCENT_START),
          gradientStop(second, PERCENT_END),
        ],
      };
    },
    spring(input: JeditSpring): JeditSpring {
      return input;
    },
  };
}

function createSourceDrafts(): JeditSourceStyleDrafts {
  return {
    comment: {},
    function: {},
    keyword: {},
    number: {},
    operator: {},
    property: {},
    punctuation: {},
    string: {},
    type: {},
    variable: {},
  };
}

function createMarkdownDrafts(): JeditMarkdownStyleDrafts {
  return {
    body: {},
    headingStrong: {},
    heading: {},
    headingSoft: {},
    listMarker: {},
    quoteMarker: {},
    quoteText: {},
    code: {},
    inlineCode: {},
    rule: {},
  };
}

function buildSourceTokens(draft: JeditSourceStyleDrafts): ReadonlyMap<JeditSourceToken, JeditStyleToken> {
  return new Map([
    [JEDIT_SOURCE_TOKEN.Comment, styleTokenFromDraft(draft.comment)],
    [JEDIT_SOURCE_TOKEN.Function, styleTokenFromDraft(draft.function)],
    [JEDIT_SOURCE_TOKEN.Keyword, styleTokenFromDraft(draft.keyword)],
    [JEDIT_SOURCE_TOKEN.Number, styleTokenFromDraft(draft.number)],
    [JEDIT_SOURCE_TOKEN.Operator, styleTokenFromDraft(draft.operator)],
    [JEDIT_SOURCE_TOKEN.Property, styleTokenFromDraft(draft.property)],
    [JEDIT_SOURCE_TOKEN.Punctuation, styleTokenFromDraft(draft.punctuation)],
    [JEDIT_SOURCE_TOKEN.String, styleTokenFromDraft(draft.string)],
    [JEDIT_SOURCE_TOKEN.Type, styleTokenFromDraft(draft.type)],
    [JEDIT_SOURCE_TOKEN.Variable, styleTokenFromDraft(draft.variable)],
  ]);
}

function buildMarkdownTokens(draft: JeditMarkdownStyleDrafts): ReadonlyMap<JeditMarkdownToken, JeditStyleToken> {
  return new Map([
    [JEDIT_MARKDOWN_TOKEN.Body, styleTokenFromDraft(draft.body)],
    [JEDIT_MARKDOWN_TOKEN.HeadingStrong, styleTokenFromDraft(draft.headingStrong)],
    [JEDIT_MARKDOWN_TOKEN.Heading, styleTokenFromDraft(draft.heading)],
    [JEDIT_MARKDOWN_TOKEN.HeadingSoft, styleTokenFromDraft(draft.headingSoft)],
    [JEDIT_MARKDOWN_TOKEN.ListMarker, styleTokenFromDraft(draft.listMarker)],
    [JEDIT_MARKDOWN_TOKEN.QuoteMarker, styleTokenFromDraft(draft.quoteMarker)],
    [JEDIT_MARKDOWN_TOKEN.QuoteText, styleTokenFromDraft(draft.quoteText)],
    [JEDIT_MARKDOWN_TOKEN.Code, styleTokenFromDraft(draft.code)],
    [JEDIT_MARKDOWN_TOKEN.InlineCode, styleTokenFromDraft(draft.inlineCode)],
    [JEDIT_MARKDOWN_TOKEN.Rule, styleTokenFromDraft(draft.rule)],
  ]);
}

function styleTokenFromDraft(draft: JeditStyleDraft): JeditStyleToken {
  const foreground = draft.foregroundColor == null ? undefined : colorEffectFromPaint(draft.foregroundColor);
  const background = draft.backgroundColor == null ? undefined : colorEffectFromPaint(draft.backgroundColor);
  return {
    char: draft.char,
    hex: foreground?.from.hex,
    fg: foreground?.from.hex,
    fgRGB: foreground?.from.rgb,
    bg: background?.from.hex,
    bgRGB: background?.from.rgb,
    modifiers: draft.modifiers,
    foregroundEffect: foreground,
    backgroundEffect: background,
    foregroundVariables: foreground == null ? [] : variablesForEffect(foreground),
    backgroundVariables: background == null ? [] : variablesForEffect(background),
    gradient: draft.gradient,
    spring: draft.spring,
  };
}

function colorEffectFromPaint(paint: ThemeColorPaint): JeditColorEffect {
  if (paint instanceof ThemeColorTransition) {
    return paint;
  }
  return {
    kind: JEDIT_COLOR_EFFECT.Solid,
    from: paint,
  };
}

function variablesForEffect(effect: JeditColorEffect): readonly string[] {
  const names = [effect.from.variableName];
  if ('to' in effect) {
    names.push(effect.to.variableName);
  }
  return names.filter((name): name is string => name != null);
}

function gradientStop(color: RgbColor | ThemeColorVariable, position: number): JeditGradientStop {
  return { color, position };
}

function inferThemeMode(token: JeditStyleToken): JeditThemeMode {
  const color = token.bgRGB ?? token.fgRGB;
  if (color == null) {
    return JEDIT_THEME_MODE.Dark;
  }
  return colorLuminance(color) >= MODE_LUMINANCE_THRESHOLD
    ? JEDIT_THEME_MODE.Light
    : JEDIT_THEME_MODE.Dark;
}

function colorLuminance(color: readonly [number, number, number]): number {
  return (color[0] * LUMINANCE_RED_WEIGHT)
    + (color[1] * LUMINANCE_GREEN_WEIGHT)
    + (color[2] * LUMINANCE_BLUE_WEIGHT);
}

function clampChannel(value: number): number {
  return Math.max(COLOR_CHANNEL_MIN, Math.min(COLOR_CHANNEL_MAX, Math.round(value)));
}

function rgbHex(red: number, green: number, blue: number): string {
  return `#${hexPair(red)}${hexPair(green)}${hexPair(blue)}`;
}

function hexPair(value: number): string {
  return value.toString(HEX_RADIX).padStart(HEX_PAIR_WIDTH, '0');
}

