}

const LOGO_PREFERRED_WIDTH = 45;
const LOGO_MAX_WIDTH = 60;
const LOGO_WIDE_SCREEN_WIDTH_RATIO = 0.32;
const LOGO_HORIZONTAL_MARGIN_COLUMNS = 2;
const LOGO_MIN_BITMAP_WIDTH = 24;
const LOGO_MIN_BITMAP_HEIGHT = 5;
const LOGO_VERTICAL_CENTER_NUMERATOR = 4;
const LOGO_VERTICAL_CENTER_DENOMINATOR = 5;
const LOGO_COVERAGE_SAMPLE_COLUMNS = 4;
const LOGO_COVERAGE_SAMPLE_ROWS = 4;
const LOGO_SOLID_THRESHOLD = 0.72;
const LOGO_DENSE_THRESHOLD = 0.45;
const LOGO_MID_THRESHOLD = 0.18;
const LOGO_FAINT_THRESHOLD = 0.05;
const LOGO_SOLID_GLYPH = '█';
const LOGO_DENSE_GLYPH = '▓';
const LOGO_MID_GLYPH = '▒';
const LOGO_FAINT_GLYPH = '░';
const LOGO_COMPACT_TEXT = 'jedit';
const LOGO_LETTER_COLOR_RATE = 1.4;
const LOGO_LETTER_PHASE_STEP_SECONDS = 0.16;
const LOGO_LETTER_COLOR_SWING = 0.18;
const LOGO_COLOR_SOURCE_WIDTH = 0.5;
const LOGO_COLOR_ANIMATION_WIDTH = 0.5;
const LOGO_MASK_BITS_PER_BYTE = 8;
const LOGO_MASK_HEX_BYTE_LENGTH = 4;
const LOGO_MASK_HEX_PREFIX_LENGTH = 2;
const LOGO_FULL_TURN_RADIANS = Math.PI * 2;
const LOGO_LETTER_BOUNCE_PERIOD_SECONDS = 10.4;
const LOGO_LETTER_BOUNCE_AMPLITUDE_ROWS = 0.34;
const LOGO_LETTER_BOUNCE_SECONDARY_AMPLITUDE_ROWS = 0.07;
const LOGO_LETTER_BOUNCE_SECONDARY_RATE = 2;
const LOGO_LETTER_SPRING_SETTLE_SECONDS = 1.2;
const LOGO_LETTER_FIXED_STEP_SECONDS = 1 / 120;
const LOGO_LETTER_SPRING_MASS = 1;
const LOGO_LETTER_SPRING_STIFFNESS = 18;
const LOGO_LETTER_SPRING_DAMPING = 8.6;
const LOGO_LETTER_SPRING_PRECISION = 0.0005;
const LOGO_LETTER_SPRING = {
  mass: LOGO_LETTER_SPRING_MASS,
  stiffness: LOGO_LETTER_SPRING_STIFFNESS,
  damping: LOGO_LETTER_SPRING_DAMPING,
  precision: LOGO_LETTER_SPRING_PRECISION,
} satisfies SpringConfig;

const TITLE_LOGO_MASK_BYTES = decodeLogoMask();
const TITLE_LOGO_SOURCE_LETTERS = titleLogoSourceLetters(TITLE_LOGO_MASK_BYTES);

export function paintTitleLogo(
  surface: Surface,
  bounds: LogoBounds,
  colors: TitleLogoColors,
  time: number,
): void {
  if (bounds.renderMode === TITLE_LOGO_RENDER_MODE.CompactText) {
    paintCompactTitleLogo(surface, bounds, colors, time);
    return;
  }

  for (const letter of titleLogoAnimatedLetters(bounds, time)) {
    paintTitleLogoLetter(surface, letter, colors);
  }
}

export function titleLogoAnimatedLetters(bounds: LogoBounds, time: number): readonly TitleLogoAnimatedLetter[] {
  return TITLE_LOGO_SOURCE_LETTERS.map((letter) => {
    const targetStart = bounds.x + Math.floor((letter.sourceX / JEDIT_LOGO_WIDTH) * bounds.width);
    const targetEnd = bounds.x + Math.ceil(((letter.sourceX + letter.sourceWidth) / JEDIT_LOGO_WIDTH) * bounds.width);
    const bounce = titleLogoSpringBounceAt(time, letter.phaseSeconds);
    const colorShift = Math.sin((time * LOGO_LETTER_COLOR_RATE) + letter.phaseSeconds) * LOGO_LETTER_COLOR_SWING;

    return {
      index: letter.index,
      sourceX: letter.sourceX,
      sourceWidth: letter.sourceWidth,
      x: targetStart,
      y: bounds.y + bounce.offset,
      width: Math.max(1, targetEnd - targetStart),
      height: bounds.height,
      bounceOffset: bounce.offset,
      targetBounceOffset: bounce.target,
      colorShift,
    };
  });
}

export function titleLogoCellBounds(screenWidth: number, screenHeight: number): LogoBounds {
  const availableWidth = Math.max(1, screenWidth - (LOGO_HORIZONTAL_MARGIN_COLUMNS * 2));
  const requestedWidth = Math.min(LOGO_MAX_WIDTH, Math.max(LOGO_PREFERRED_WIDTH, Math.floor(screenWidth * LOGO_WIDE_SCREEN_WIDTH_RATIO)));
  const maxWidth = Math.max(1, Math.min(availableWidth, requestedWidth));
  const naturalHeight = Math.max(1, Math.floor(maxWidth * (JEDIT_LOGO_HEIGHT / JEDIT_LOGO_WIDTH)));
  const height = Math.min(screenHeight, naturalHeight);
  const width = Math.min(maxWidth, Math.max(1, Math.floor(height * (JEDIT_LOGO_WIDTH / JEDIT_LOGO_HEIGHT))));
  if (width < LOGO_MIN_BITMAP_WIDTH || height < LOGO_MIN_BITMAP_HEIGHT) {
    return compactTitleLogoCellBounds(screenWidth, screenHeight);
  }

  const centerY = Math.floor((screenHeight * LOGO_VERTICAL_CENTER_NUMERATOR) / LOGO_VERTICAL_CENTER_DENOMINATOR);
  const maxY = Math.max(0, screenHeight - height);
  return {
    x: Math.floor((screenWidth - width) / 2),
    y: Math.min(maxY, Math.max(0, Math.floor(centerY - (height / 2)))),
    width,
    height,
    renderMode: TITLE_LOGO_RENDER_MODE.Bitmap,
  };
}

function compactTitleLogoCellBounds(screenWidth: number, screenHeight: number): LogoBounds {
  const width = Math.min(Math.max(1, screenWidth), LOGO_COMPACT_TEXT.length);
  const height = Math.min(1, Math.max(1, screenHeight));
  const centerY = Math.floor((screenHeight * LOGO_VERTICAL_CENTER_NUMERATOR) / LOGO_VERTICAL_CENTER_DENOMINATOR);
  return {
    x: Math.max(0, Math.floor((screenWidth - width) / 2)),
    y: Math.max(0, Math.min(screenHeight - height, centerY)),
    width,
    height,
    renderMode: TITLE_LOGO_RENDER_MODE.CompactText,
  };
}

function paintCompactTitleLogo(
  surface: Surface,
  bounds: LogoBounds,
  colors: TitleLogoColors,
  time: number,
): void {
  const text = LOGO_COMPACT_TEXT.slice(0, bounds.width);
  for (let index = 0; index < text.length; index++) {
    const char = text[index];
    if (char == null) {
      continue;
    }
    const x = bounds.x + index;
    const y = bounds.y;
    if (x < 0 || x >= surface.width || y < 0 || y >= surface.height) {
      continue;
    }
    const phaseSeconds = index * LOGO_LETTER_PHASE_STEP_SECONDS;
    const bounce = titleLogoSpringBounceAt(time, phaseSeconds);
    const colorShift = Math.sin((time * LOGO_LETTER_COLOR_RATE) + phaseSeconds) * LOGO_LETTER_COLOR_SWING;
    surface.set(x, y, {
      char,
      fgRGB: mixColor(colors.accent, colors.info, compactLogoColorRatio(index, text.length, colorShift + (bounce.offset * LOGO_LETTER_COLOR_SWING))),
      bgRGB: colors.surface,
      modifiers: [JEDIT_TEXT_MODIFIER.Bold],
    });
  }
}

function paintTitleLogoLetter(
  surface: Surface,
  letter: TitleLogoAnimatedLetter,
  colors: TitleLogoColors,
): void {
  const minY = Math.floor(letter.y);
  const maxY = Math.ceil(letter.y + letter.height);
  for (let y = minY; y < maxY; y++) {
    if (y < 0 || y >= surface.height) {
      continue;
    }
    const localRow = y - letter.y;

    for (let col = 0; col < letter.width; col++) {
      const x = letter.x + col;
      if (x < 0 || x >= surface.width) {
        continue;
      }

      const coverage = logoLetterCoverageAt(col, localRow, letter);
      const char = titleLogoGlyphForCoverage(coverage);
      if (char == null) {
        continue;
      }

      surface.set(x, y, {
        char,
        fgRGB: mixColor(colors.accent, colors.info, titleLogoCellColorRatio(letter, col)),
        bgRGB: colors.surface,
        modifiers: [JEDIT_TEXT_MODIFIER.Bold],
      });
    }
  }
}

function logoLetterCoverageAt(
  col: number,
  row: number,
  letter: TitleLogoAnimatedLetter,
): number {
  let covered = 0;
  const sampleCount = LOGO_COVERAGE_SAMPLE_COLUMNS * LOGO_COVERAGE_SAMPLE_ROWS;
  for (let sampleY = 0; sampleY < LOGO_COVERAGE_SAMPLE_ROWS; sampleY++) {
    for (let sampleX = 0; sampleX < LOGO_COVERAGE_SAMPLE_COLUMNS; sampleX++) {
      const logoX = letter.sourceX + Math.floor(
        ((col + ((sampleX + 0.5) / LOGO_COVERAGE_SAMPLE_COLUMNS)) / letter.width) * letter.sourceWidth,
      );
      const logoY = Math.floor(
        ((row + ((sampleY + 0.5) / LOGO_COVERAGE_SAMPLE_ROWS)) / letter.height) * JEDIT_LOGO_HEIGHT,
      );
      if (logoMaskBit(TITLE_LOGO_MASK_BYTES, logoX, logoY)) {
        covered += 1;
      }
    }
  }
  return covered / sampleCount;
}

function titleLogoGlyphForCoverage(coverage: number): string | undefined {
  if (coverage >= LOGO_SOLID_THRESHOLD) {
    return LOGO_SOLID_GLYPH;
  }
  if (coverage >= LOGO_DENSE_THRESHOLD) {
    return LOGO_DENSE_GLYPH;
  }
  if (coverage >= LOGO_MID_THRESHOLD) {
    return LOGO_MID_GLYPH;
  }
  if (coverage >= LOGO_FAINT_THRESHOLD) {
    return LOGO_FAINT_GLYPH;
  }
  return undefined;
}

function titleLogoCellColorRatio(letter: TitleLogoAnimatedLetter, col: number): number {
  const sourceCellRatio = (letter.sourceX + (((col + 0.5) / letter.width) * letter.sourceWidth)) / JEDIT_LOGO_WIDTH;
  return clamp(
    (sourceCellRatio * LOGO_COLOR_SOURCE_WIDTH)
      + ((sourceCellRatio + letter.colorShift) * LOGO_COLOR_ANIMATION_WIDTH),
  );
}

function compactLogoColorRatio(index: number, length: number, colorShift: number): number {
  const sourceRatio = index / Math.max(1, length - 1);
  return clamp(
    (sourceRatio * LOGO_COLOR_SOURCE_WIDTH)
      + ((sourceRatio + colorShift) * LOGO_COLOR_ANIMATION_WIDTH),
  );
}

function titleLogoSpringBounceAt(
  time: number,
  phaseSeconds: number,
): { readonly offset: number; readonly target: number } {
  const simulationEnd = time + phaseSeconds;
  const simulationStart = simulationEnd - LOGO_LETTER_SPRING_SETTLE_SECONDS;
  let state = createSpringState(titleLogoBounceTargetAt(simulationStart));
  let simulated = simulationStart;

  while (simulated < simulationEnd) {
    const stepSeconds = Math.min(LOGO_LETTER_FIXED_STEP_SECONDS, simulationEnd - simulated);
    state = springStep(state, titleLogoBounceTargetAt(simulated), LOGO_LETTER_SPRING, stepSeconds);
    simulated += stepSeconds;
  }

  return {
    offset: state.value,
    target: titleLogoBounceTargetAt(simulationEnd),
  };
}

function titleLogoBounceTargetAt(time: number): number {
  const angle = (positiveModulo(time, LOGO_LETTER_BOUNCE_PERIOD_SECONDS) / LOGO_LETTER_BOUNCE_PERIOD_SECONDS)
    * LOGO_FULL_TURN_RADIANS;
  return (Math.sin(angle) * LOGO_LETTER_BOUNCE_AMPLITUDE_ROWS)
    + (Math.sin(angle * LOGO_LETTER_BOUNCE_SECONDARY_RATE) * LOGO_LETTER_BOUNCE_SECONDARY_AMPLITUDE_ROWS);
}

function positiveModulo(value: number, divisor: number): number {
  return ((value % divisor) + divisor) % divisor;
}

function titleLogoSourceLetters(mask: readonly (readonly number[])[]): readonly TitleLogoSourceLetter[] {
  const letters: TitleLogoSourceLetter[] = [];
  let rangeStart: number | undefined;

  for (let x = 0; x < JEDIT_LOGO_WIDTH; x++) {
    const occupied = titleLogoColumnOccupied(mask, x);
    if (occupied && rangeStart == null) {
      rangeStart = x;
    }

    if ((rangeStart != null) && (!occupied || x === JEDIT_LOGO_WIDTH - 1)) {
      const rangeEnd = occupied && x === JEDIT_LOGO_WIDTH - 1 ? x : x - 1;
      letters.push({
        index: letters.length,
        sourceX: rangeStart,
        sourceWidth: rangeEnd - rangeStart + 1,
        phaseSeconds: letters.length * LOGO_LETTER_PHASE_STEP_SECONDS,
      });
      rangeStart = undefined;
    }
  }

  return letters;
}

function titleLogoColumnOccupied(mask: readonly (readonly number[])[], x: number): boolean {
  for (let y = 0; y < JEDIT_LOGO_HEIGHT; y++) {
    if (logoMaskBit(mask, x, y)) {
      return true;
    }
  }
  return false;
}

function logoMaskBit(mask: readonly (readonly number[])[], x: number, y: number): boolean {
  if (x < 0 || x >= JEDIT_LOGO_WIDTH || y < 0 || y >= JEDIT_LOGO_HEIGHT) {
    return false;
  }
  const row = mask[y];
  return row != null && (row[Math.floor(x / LOGO_MASK_BITS_PER_BYTE)]! & (1 << (LOGO_MASK_BITS_PER_BYTE - 1 - (x % LOGO_MASK_BITS_PER_BYTE)))) !== 0;
}

function decodeLogoMask(): readonly (readonly number[])[] {
  return JEDIT_LOGO_MASK.map((row) => {
    const bytes: number[] = [];
    for (let index = 0; index < row.length; index += LOGO_MASK_HEX_BYTE_LENGTH) {
      bytes.push(parseInt(row.slice(index + LOGO_MASK_HEX_PREFIX_LENGTH, index + LOGO_MASK_HEX_BYTE_LENGTH), 16));
    }
    return bytes;
  });
}

function mixColor(from: Color3, to: Color3, ratio: number): Color3 {
  const clamped = clamp(ratio);
  return [
    Math.round(from[0] + ((to[0] - from[0]) * clamped)),
    Math.round(from[1] + ((to[1] - from[1]) * clamped)),
    Math.round(from[2] + ((to[2] - from[2]) * clamped)),
  ];
}

function clamp(value: number): number {
  return Math.max(0, Math.min(1, value));
}

import type { TitleMeshSource, TitleMeshTriangle, TitleMeshVector3 } from '../ports/title-mesh.js';
import {
  EmptyMeshError,
  InvalidMeshHeightError,
  MeshTriangleIndexOutOfRangeError,
  MeshVertexIndexOutOfRangeError,
} from '../domain/errors.js';

export type { TitleMeshSource, TitleMeshTriangle, TitleMeshVector3 };

export interface TitleMeshBounds {
  readonly min: TitleMeshVector3;
  readonly max: TitleMeshVector3;
}

export interface TitleMesh {
  readonly vertices: readonly TitleMeshVector3[];
  readonly triangles: readonly TitleMeshTriangle[];
  readonly bounds: TitleMeshBounds;
  readonly height: number;
  readonly footprintRadius: number;
  readonly root: TitleMeshBvhNode;
}

export interface TitleMeshHit {
  readonly distance: number;
  readonly normal: TitleMeshVector3;
}

interface TitleMeshPlacement {
  readonly height: number;
  readonly yawRadians: number;
  readonly centerX: number;
  readonly floorY: number;
  readonly centerZ: number;
}

interface TitleMeshTriangleData {
  readonly indices: TitleMeshTriangle;
  readonly bounds: TitleMeshBounds;
  readonly center: TitleMeshVector3;
}

interface TitleMeshBvhNode {
  readonly bounds: TitleMeshBounds;
  readonly triangleIndices: readonly number[];
  readonly left?: TitleMeshBvhNode;
  readonly right?: TitleMeshBvhNode;
}

type Axis = typeof AXIS_X | typeof AXIS_Y | typeof AXIS_Z;

const AXIS_X = 0;
const AXIS_Y = 1;
const AXIS_Z = 2;
const TITLE_BUNNY_HEIGHT = 2.35;
const TITLE_BUNNY_YAW_RADIANS = Math.PI * 0.18;
const TITLE_BUNNY_CENTER_X = -0.85;
const TITLE_BUNNY_FLOOR_Y = 0;
const TITLE_BUNNY_CENTER_Z = -0.15;
const BVH_LEAF_TRIANGLE_COUNT = 8;
const INTERSECTION_EPSILON = 0.000001;
const EMPTY_TRIANGLE_INDICES: readonly number[] = [];

export function createTitleBunnyMesh(source: TitleMeshSource): TitleMesh {
  return createTitleMesh(source, {
    height: TITLE_BUNNY_HEIGHT,
    yawRadians: TITLE_BUNNY_YAW_RADIANS,
    centerX: TITLE_BUNNY_CENTER_X,
    floorY: TITLE_BUNNY_FLOOR_Y,
    centerZ: TITLE_BUNNY_CENTER_Z,
  });
}

export function nearestTitleMeshHit(
  origin: TitleMeshVector3,
  ray: TitleMeshVector3,
  mesh: TitleMesh,
): TitleMeshHit | undefined {
  let nearest: TitleMeshHit | undefined;
  visitMeshNode(mesh.root);
  return nearest;

  function visitMeshNode(node: TitleMeshBvhNode): void {
    if (!rayIntersectsBounds(origin, ray, node.bounds, nearest?.distance ?? Infinity)) {
      return;
    }

    if (node.triangleIndices.length > 0) {
      for (const triangleIndex of node.triangleIndices) {
        const hit = intersectTitleMeshTriangle(origin, ray, mesh, triangleIndex);
        if (hit != null && (nearest == null || hit.distance < nearest.distance)) {
          nearest = hit;
        }
      }
      return;
    }

    if (node.left != null) {
      visitMeshNode(node.left);
    }
    if (node.right != null) {
      visitMeshNode(node.right);
    }
  }
}

function createTitleMesh(source: TitleMeshSource, placement: TitleMeshPlacement): TitleMesh {
  const sourceBounds = boundsForVertices(source.vertices);
  const vertices = source.vertices.map((vertex) => transformVertex(vertex, sourceBounds, placement));
  const triangles = source.triangles.map((indices) => triangleData(vertices, indices));
  if (triangles.length === 0) {
    throw new EmptyMeshError('Title mesh must contain at least one triangle.');
  }

  const triangleIndices = triangles.map((_, index) => index);
  const bounds = boundsForVertices(vertices);
  return {
    vertices,
    triangles: triangles.map((triangle) => triangle.indices),
    bounds,
    height: bounds.max[AXIS_Y] - bounds.min[AXIS_Y],
    footprintRadius: footprintRadiusForVertices(vertices, placement.centerX, placement.centerZ),
    root: buildBvhNode(triangles, triangleIndices),
  };
}

function transformVertex(vertex: TitleMeshVector3, bounds: TitleMeshBounds, placement: TitleMeshPlacement): TitleMeshVector3 {
  const sourceHeight = bounds.max[AXIS_Y] - bounds.min[AXIS_Y];
  if (sourceHeight <= 0) {
    throw new InvalidMeshHeightError('Title mesh source height must be greater than zero.');
  }

  const sourceCenterX = (bounds.min[AXIS_X] + bounds.max[AXIS_X]) / 2;
  const sourceCenterZ = (bounds.min[AXIS_Z] + bounds.max[AXIS_Z]) / 2;
  const scale = placement.height / sourceHeight;
  const x = (vertex[AXIS_X] - sourceCenterX) * scale;
  const y = ((vertex[AXIS_Y] - bounds.min[AXIS_Y]) * scale) + placement.floorY;
  const z = (vertex[AXIS_Z] - sourceCenterZ) * scale;
  const cos = Math.cos(placement.yawRadians);
  const sin = Math.sin(placement.yawRadians);

  return [
    placement.centerX + ((x * cos) - (z * sin)),
    y,
    placement.centerZ + ((x * sin) + (z * cos)),
  ];
}

function buildBvhNode(triangles: readonly TitleMeshTriangleData[], triangleIndices: readonly number[]): TitleMeshBvhNode {
  const bounds = boundsForTriangles(triangles, triangleIndices);
  if (triangleIndices.length <= BVH_LEAF_TRIANGLE_COUNT) {
    return { bounds, triangleIndices };
  }

  const axis = widestAxis(bounds);
  const sorted = [...triangleIndices].sort((left, right) => (
    triangleAt(triangles, left).center[axis] - triangleAt(triangles, right).center[axis]
  ));
  const split = Math.floor(sorted.length / 2);
  const leftIndices = sorted.slice(0, split);
  const rightIndices = sorted.slice(split);
  if (leftIndices.length === 0 || rightIndices.length === 0) {
    return { bounds, triangleIndices };
  }

  return {
    bounds,
    triangleIndices: EMPTY_TRIANGLE_INDICES,
    left: buildBvhNode(triangles, leftIndices),
    right: buildBvhNode(triangles, rightIndices),
  };
}

function intersectTitleMeshTriangle(
  origin: TitleMeshVector3,
  ray: TitleMeshVector3,
  mesh: TitleMesh,
  triangleIndex: number,
): TitleMeshHit | undefined {
  const indices = mesh.triangles[triangleIndex];
  if (indices == null) {
    return undefined;
  }
  const a = vertexAt(mesh.vertices, indices[0]);
  const b = vertexAt(mesh.vertices, indices[1]);
  const c = vertexAt(mesh.vertices, indices[2]);
  const edgeA = sub(b, a);
  const edgeB = sub(c, a);
  const rayCrossEdgeB = cross(ray, edgeB);
  const determinant = dot(edgeA, rayCrossEdgeB);
  if (Math.abs(determinant) <= INTERSECTION_EPSILON) {
    return undefined;
  }

  const inverseDeterminant = 1 / determinant;
  const originToA = sub(origin, a);
  const u = dot(originToA, rayCrossEdgeB) * inverseDeterminant;
  if (u < 0 || u > 1) {
    return undefined;
  }

  const originCrossEdgeA = cross(originToA, edgeA);
  const v = dot(ray, originCrossEdgeA) * inverseDeterminant;
  if (v < 0 || u + v > 1) {
    return undefined;
  }

  const distance = dot(edgeB, originCrossEdgeA) * inverseDeterminant;
  if (distance <= INTERSECTION_EPSILON) {
    return undefined;
  }

  const normal = normalize(cross(edgeA, edgeB));
  return {
    distance,
    normal: dot(normal, ray) > 0 ? scale(normal, -1) : normal,
  };
}

function rayIntersectsBounds(
  origin: TitleMeshVector3,
  ray: TitleMeshVector3,
  bounds: TitleMeshBounds,
  maxDistance: number,
): boolean {
  let nearDistance = 0;
  let farDistance = maxDistance;

  for (const axis of [AXIS_X, AXIS_Y, AXIS_Z] as const) {
    const direction = ray[axis];
    if (Math.abs(direction) <= INTERSECTION_EPSILON) {
      if (origin[axis] < bounds.min[axis] || origin[axis] > bounds.max[axis]) {
        return false;
      }
      continue;
    }

    const inverseDirection = 1 / direction;
    const first = (bounds.min[axis] - origin[axis]) * inverseDirection;
    const second = (bounds.max[axis] - origin[axis]) * inverseDirection;
    nearDistance = Math.max(nearDistance, Math.min(first, second));
    farDistance = Math.min(farDistance, Math.max(first, second));
    if (farDistance < nearDistance) {
      return false;
    }
  }

  return farDistance > 0;
}

function triangleData(vertices: readonly TitleMeshVector3[], indices: TitleMeshTriangle): TitleMeshTriangleData {
  const a = vertexAt(vertices, indices[0]);
  const b = vertexAt(vertices, indices[1]);
  const c = vertexAt(vertices, indices[2]);
  const bounds = boundsForVertices([a, b, c]);
  return {
    indices,
    bounds,
    center: [
      (a[AXIS_X] + b[AXIS_X] + c[AXIS_X]) / 3,
      (a[AXIS_Y] + b[AXIS_Y] + c[AXIS_Y]) / 3,
      (a[AXIS_Z] + b[AXIS_Z] + c[AXIS_Z]) / 3,
    ],
  };
}

function boundsForTriangles(triangles: readonly TitleMeshTriangleData[], indices: readonly number[]): TitleMeshBounds {
  const first = triangleAt(triangles, indices[0] ?? -1).bounds;
  let min = first.min;
  let max = first.max;
  for (const index of indices.slice(1)) {
    const bounds = triangleAt(triangles, index).bounds;
    min = minVector(min, bounds.min);
    max = maxVector(max, bounds.max);
  }
  return { min, max };
}

function boundsForVertices(vertices: readonly TitleMeshVector3[]): TitleMeshBounds {
  const first = vertices[0];
  if (first == null) {
    throw new EmptyMeshError('Title mesh must contain at least one vertex.');
  }

  let min = first;
  let max = first;
  for (const vertex of vertices.slice(1)) {
    min = minVector(min, vertex);
    max = maxVector(max, vertex);
  }
  return { min, max };
}

function footprintRadiusForVertices(vertices: readonly TitleMeshVector3[], centerX: number, centerZ: number): number {
  let radius = 0;
  for (const vertex of vertices) {
    const x = vertex[AXIS_X] - centerX;
    const z = vertex[AXIS_Z] - centerZ;
    radius = Math.max(radius, Math.sqrt((x * x) + (z * z)));
  }
  return radius;
}

function widestAxis(bounds: TitleMeshBounds): Axis {
  const width = bounds.max[AXIS_X] - bounds.min[AXIS_X];
  const height = bounds.max[AXIS_Y] - bounds.min[AXIS_Y];
  const depth = bounds.max[AXIS_Z] - bounds.min[AXIS_Z];
  if (height >= width && height >= depth) {
    return AXIS_Y;
  }
  return depth >= width ? AXIS_Z : AXIS_X;
}

function triangleAt(triangles: readonly TitleMeshTriangleData[], index: number): TitleMeshTriangleData {
  const triangle = triangles[index];
  if (triangle == null) {
    throw new MeshTriangleIndexOutOfRangeError('Title mesh triangle index is out of range.');
  }
  return triangle;
}

function vertexAt(vertices: readonly TitleMeshVector3[], index: number): TitleMeshVector3 {
  const vertex = vertices[index];
  if (vertex == null) {
    throw new MeshVertexIndexOutOfRangeError('Title mesh vertex index is out of range.');
  }
  return vertex;
}

function minVector(a: TitleMeshVector3, b: TitleMeshVector3): TitleMeshVector3 {
  return [Math.min(a[AXIS_X], b[AXIS_X]), Math.min(a[AXIS_Y], b[AXIS_Y]), Math.min(a[AXIS_Z], b[AXIS_Z])];
}

function maxVector(a: TitleMeshVector3, b: TitleMeshVector3): TitleMeshVector3 {
  return [Math.max(a[AXIS_X], b[AXIS_X]), Math.max(a[AXIS_Y], b[AXIS_Y]), Math.max(a[AXIS_Z], b[AXIS_Z])];
}

function normalize(vector: TitleMeshVector3): TitleMeshVector3 {
  const length = Math.sqrt(dot(vector, vector));
  return length === 0 ? [0, 0, 0] : scale(vector, 1 / length);
}

function dot(a: TitleMeshVector3, b: TitleMeshVector3): number {
  return (a[AXIS_X] * b[AXIS_X]) + (a[AXIS_Y] * b[AXIS_Y]) + (a[AXIS_Z] * b[AXIS_Z]);
}

function cross(a: TitleMeshVector3, b: TitleMeshVector3): TitleMeshVector3 {
  return [
    (a[AXIS_Y] * b[AXIS_Z]) - (a[AXIS_Z] * b[AXIS_Y]),
    (a[AXIS_Z] * b[AXIS_X]) - (a[AXIS_X] * b[AXIS_Z]),
    (a[AXIS_X] * b[AXIS_Y]) - (a[AXIS_Y] * b[AXIS_X]),
  ];
}

function sub(a: TitleMeshVector3, b: TitleMeshVector3): TitleMeshVector3 {
  return [a[AXIS_X] - b[AXIS_X], a[AXIS_Y] - b[AXIS_Y], a[AXIS_Z] - b[AXIS_Z]];
}

function scale(vector: TitleMeshVector3, scalar: number): TitleMeshVector3 {
  return [vector[AXIS_X] * scalar, vector[AXIS_Y] * scalar, vector[AXIS_Z] * scalar];
}

import type { RGB } from './averaging-braille-canvas.js';
import { nearestTitleMeshHit, type TitleMesh } from './title-mesh.js';

export const TITLE_SCENE_SHAPE_KIND = {
  Sphere: 'sphere',
  Column: 'column',
  Mesh: 'mesh',
} as const;

export type TitleSceneShapeKind = typeof TITLE_SCENE_SHAPE_KIND[keyof typeof TITLE_SCENE_SHAPE_KIND];
export type TitleScenePrimitiveShapeKind =
  | typeof TITLE_SCENE_SHAPE_KIND.Sphere
  | typeof TITLE_SCENE_SHAPE_KIND.Column;
export type TitleSceneVector3 = readonly [number, number, number];
export type TitleSceneColor = RGB;

export interface TitleSceneColorSet {
  readonly accent: TitleSceneColor;
  readonly info: TitleSceneColor;
  readonly success: TitleSceneColor;
  readonly ink: TitleSceneColor;
  readonly muted: TitleSceneColor;
  readonly surface: TitleSceneColor;
}

interface TitleSceneBaseObject {
  readonly position: TitleSceneVector3;
  readonly radius: number;
  readonly footprintRadius: number;
  readonly height: number;
  readonly color: TitleSceneColor;
  readonly reflectivity: number;
}

export interface TitleScenePrimitiveObject extends TitleSceneBaseObject {
  readonly kind: TitleScenePrimitiveShapeKind;
}

export interface TitleSceneMeshObject extends TitleSceneBaseObject {
  readonly kind: typeof TITLE_SCENE_SHAPE_KIND.Mesh;
  readonly mesh: TitleMesh;
}

export type TitleSceneObject = TitleScenePrimitiveObject | TitleSceneMeshObject;

export interface TitleSceneCameraPlacement {
  readonly angle: number;
  readonly radius: number;
}

export interface TitleScene {
  readonly camera: TitleSceneCameraPlacement;
  readonly objects: readonly TitleSceneObject[];
}

export interface TitleSceneObjectHit {
  readonly object: TitleSceneObject;
  readonly distance: number;
  readonly normal: TitleSceneVector3;
}

const CAMERA_MIN_RADIUS = 7.2;
const CAMERA_RADIUS_SPAN = 3;
const BUNNY_SCENE_CAMERA_ANGLE = -0.58;
const BUNNY_SCENE_CAMERA_RADIUS = 5.4;
const FULL_TURN_RADIANS = Math.PI * 2;
const SCENE_OBJECT_COUNT = 6;
const BUNNY_SCENE_MIRROR_SPHERE_RADIUS = 1.25;
const BUNNY_SCENE_MIRROR_SPHERE_HEIGHT = BUNNY_SCENE_MIRROR_SPHERE_RADIUS * 2;
const BUNNY_SCENE_MIRROR_SPHERE_FOOTPRINT_RADIUS = BUNNY_SCENE_MIRROR_SPHERE_RADIUS;
const BUNNY_SCENE_MIRROR_SPHERE_REFLECTIVITY = 1;
const BUNNY_SCENE_MESH_REFLECTIVITY = 0.18;
const PRIMARY_SPHERE_MIN_RADIUS = 1.05;
const PRIMARY_SPHERE_RADIUS_SPAN = 0.22;
const SECONDARY_MIN_RADIUS = 0.45;
const SECONDARY_RADIUS_SPAN = 0.42;
const FALLBACK_SECONDARY_RADIUS = 0.42;
const COLUMN_MIN_HEIGHT = 1.1;
const COLUMN_HEIGHT_SPAN = 1.4;
const POSITION_JITTER = 0.32;
const PLACEMENT_ATTEMPTS = 18;
const PRNG_SEED_SCALE = 0xffffffff;
const PRNG_STEP = 0x6d2b79f5;
const PRNG_DIVISOR = 4294967296;
const COLUMN_RAY_EPSILON = 0.000001;
const COLUMN_FLOOR_Y = 0;
export const TITLE_SCENE_OBJECT_MARGIN = 0.28;

const POSITION_TEMPLATES: readonly (readonly [number, number])[] = [
  [0, 0],
  [2.8, 1.7],
  [-2.7, -1.5],
  [3.2, -1.6],
  [-3.1, 1.8],
  [0.8, -3.3],
];

export function generateTitleScene(seed: number, colors: TitleSceneColorSet, mesh?: TitleMesh): TitleScene {
  if (mesh != null) {
    return {
      camera: titleBunnySceneCameraPlacement(),
      objects: createBunnySceneObjects(colors, mesh),
    };
  }

  const random = seededRandom(seed);
  const objects: TitleSceneObject[] = [];
  for (let index = 0; index < SCENE_OBJECT_COUNT; index += 1) {
    const object = placeSceneObject(index, random, colors, objects, mesh);
    objects.push(object);
  }
  return {
    camera: titleSceneCameraPlacement(seed),
    objects,
  };
}

export function titleSceneCameraPlacement(seed: number): TitleSceneCameraPlacement {
  const random = seededRandom(seed + 1);
  return {
    angle: random() * FULL_TURN_RADIANS,
    radius: CAMERA_MIN_RADIUS + (random() * CAMERA_RADIUS_SPAN),
  };
}

export function titleBunnySceneCameraPlacement(): TitleSceneCameraPlacement {
  return {
    angle: BUNNY_SCENE_CAMERA_ANGLE,
    radius: BUNNY_SCENE_CAMERA_RADIUS,
  };
}

export function nearestTitleSceneObjectHit(
  origin: TitleSceneVector3,
  ray: TitleSceneVector3,
  objects: readonly TitleSceneObject[],
  ignoredObject?: TitleSceneObject,
): TitleSceneObjectHit | undefined {
  let nearest: TitleSceneObjectHit | undefined;
  for (const object of objects) {
    if (object === ignoredObject) {
      continue;
    }
    const hit = titleSceneObjectHit(origin, ray, object);
    if (hit != null && hit.distance > 0 && (nearest == null || hit.distance < nearest.distance)) {
      nearest = hit;
    }
  }
  return nearest;
}

export function intersectsTitleSceneObjectAlongRay(
  origin: TitleSceneVector3,
  ray: TitleSceneVector3,
  object: TitleSceneObject,
): boolean {
  const hit = titleSceneObjectHit(origin, ray, object);
  return hit != null && hit.distance > 0;
}

function placeSceneObject(
  index: number,
  random: () => number,
  colors: TitleSceneColorSet,
  existing: readonly TitleSceneObject[],
  mesh: TitleMesh | undefined,
): TitleSceneObject {
  for (let attempt = 0; attempt < PLACEMENT_ATTEMPTS; attempt += 1) {
    const candidate = createSceneObject(index, random, colors, mesh);
    if (!overlapsSceneObjects(candidate, existing)) {
      return candidate;
    }
  }
  return createFallbackSceneObject(index, colors, mesh);
}

function createSceneObject(
  index: number,
  random: () => number,
  colors: TitleSceneColorSet,
  mesh: TitleMesh | undefined,
): TitleSceneObject {
  if (index === 0 && mesh != null) {
    return createMeshSceneObject(colors, mesh);
  }

  const kind = sceneShapeKind(index, random);
  const template = POSITION_TEMPLATES[index % POSITION_TEMPLATES.length] ?? [0, 0];
  const radius = index === 0
    ? PRIMARY_SPHERE_MIN_RADIUS + (random() * PRIMARY_SPHERE_RADIUS_SPAN)
    : SECONDARY_MIN_RADIUS + (random() * SECONDARY_RADIUS_SPAN);
  const height = kind === TITLE_SCENE_SHAPE_KIND.Column
    ? COLUMN_MIN_HEIGHT + (random() * COLUMN_HEIGHT_SPAN)
    : radius * 2;
  const x = template[0] + jitter(random);
  const z = template[1] + jitter(random);
  return {
    kind,
    position: [x, height / 2, z],
    radius,
    footprintRadius: radius,
    height,
    color: materialColor(index, random, colors),
    reflectivity: 0.18 + (random() * 0.34),
  };
}

function createFallbackSceneObject(index: number, colors: TitleSceneColorSet, mesh: TitleMesh | undefined): TitleSceneObject {
  if (index === 0 && mesh != null) {
    return createMeshSceneObject(colors, mesh);
  }

  const kind = index === 1 ? TITLE_SCENE_SHAPE_KIND.Column : TITLE_SCENE_SHAPE_KIND.Sphere;
  const template = POSITION_TEMPLATES[index % POSITION_TEMPLATES.length] ?? [0, 0];
  const radius = index === 0 ? PRIMARY_SPHERE_MIN_RADIUS : FALLBACK_SECONDARY_RADIUS;
  const height = kind === TITLE_SCENE_SHAPE_KIND.Column ? COLUMN_MIN_HEIGHT : radius * 2;
  return {
    kind,
    position: [template[0], height / 2, template[1]],
    radius,
    footprintRadius: radius,
    height,
    color: materialColor(index, seededRandom(index), colors),
    reflectivity: 0.18,
  };
}

function createBunnySceneObjects(colors: TitleSceneColorSet, mesh: TitleMesh): readonly TitleSceneObject[] {
  return [
    createMeshSceneObject(colors, mesh),
    createMirrorSphere(colors),
  ];
}

function createMeshSceneObject(colors: TitleSceneColorSet, mesh: TitleMesh): TitleSceneMeshObject {
  const bounds = mesh.bounds;
  return {
    kind: TITLE_SCENE_SHAPE_KIND.Mesh,
    mesh,
    position: [
      (bounds.min[0] + bounds.max[0]) / 2,
      mesh.height / 2,
      (bounds.min[2] + bounds.max[2]) / 2,
    ],
    radius: mesh.footprintRadius,
    footprintRadius: mesh.footprintRadius,
    height: mesh.height,
    color: colors.accent,
    reflectivity: BUNNY_SCENE_MESH_REFLECTIVITY,
  };
}

function createMirrorSphere(colors: TitleSceneColorSet): TitleScenePrimitiveObject {
  return {
    kind: TITLE_SCENE_SHAPE_KIND.Sphere,
    position: [1.34, BUNNY_SCENE_MIRROR_SPHERE_RADIUS, 0.55],
    radius: BUNNY_SCENE_MIRROR_SPHERE_RADIUS,
    footprintRadius: BUNNY_SCENE_MIRROR_SPHERE_FOOTPRINT_RADIUS,
    height: BUNNY_SCENE_MIRROR_SPHERE_HEIGHT,
    color: colors.ink,
    reflectivity: BUNNY_SCENE_MIRROR_SPHERE_REFLECTIVITY,
  };
}

function sceneShapeKind(index: number, random: () => number): TitleScenePrimitiveShapeKind {
  if (index === 0) {
    return TITLE_SCENE_SHAPE_KIND.Sphere;
  }
  if (index === 1) {
    return TITLE_SCENE_SHAPE_KIND.Column;
  }
  return random() > 0.55 ? TITLE_SCENE_SHAPE_KIND.Column : TITLE_SCENE_SHAPE_KIND.Sphere;
}

function materialColor(index: number, random: () => number, colors: TitleSceneColorSet): TitleSceneColor {
  const palette: readonly TitleSceneColor[] = [
    colors.accent,
    colors.success,
    colors.info,
    colors.muted,
    colors.ink,
  ];
  return palette[(index + Math.floor(random() * palette.length)) % palette.length] ?? colors.accent;
}

function overlapsSceneObjects(candidate: TitleSceneObject, existing: readonly TitleSceneObject[]): boolean {
  return existing.some((object) => {
    const dx = candidate.position[0] - object.position[0];
    const dz = candidate.position[2] - object.position[2];
    const distance = Math.sqrt((dx * dx) + (dz * dz));
    return distance < candidate.footprintRadius + object.footprintRadius + TITLE_SCENE_OBJECT_MARGIN;
  });
}

function titleSceneObjectHit(
  origin: TitleSceneVector3,
  ray: TitleSceneVector3,
  object: TitleSceneObject,
): TitleSceneObjectHit | undefined {
  switch (object.kind) {
    case TITLE_SCENE_SHAPE_KIND.Column:
      return columnHit(origin, ray, object);
    case TITLE_SCENE_SHAPE_KIND.Mesh:
      return meshHit(origin, ray, object);
    case TITLE_SCENE_SHAPE_KIND.Sphere:
      return sphereHit(origin, ray, object);
  }
}

function sphereHit(origin: TitleSceneVector3, ray: TitleSceneVector3, object: TitleSceneObject): TitleSceneObjectHit | undefined {
  const distance = intersectSphere(origin, ray, object.position, object.radius);
  if (distance <= 0) {
    return undefined;
  }
  const point = add(origin, scale(ray, distance));
  return {
    object,
    distance,
    normal: normalize(sub(point, object.position)),
  };
}

function columnHit(origin: TitleSceneVector3, ray: TitleSceneVector3, object: TitleSceneObject): TitleSceneObjectHit | undefined {
  let nearestDistance = -1;
  let nearestNormal: TitleSceneVector3 | undefined;

  // Check side
  const sideDistance = intersectColumnSide(origin, ray, object);
  if (sideDistance > 0) {
    nearestDistance = sideDistance;
    const point = add(origin, scale(ray, sideDistance));
    nearestNormal = normalize([point[0] - object.position[0], 0, point[2] - object.position[2]]);
  }

  // Check top cap (y = object.height)
  const topDistance = intersectColumnCap(origin, ray, object, object.height);
  if (topDistance > 0 && (nearestDistance < 0 || topDistance < nearestDistance)) {
    nearestDistance = topDistance;
    nearestNormal = [0, 1, 0];
  }

  // Check bottom cap (y = COLUMN_FLOOR_Y)
  const bottomDistance = intersectColumnCap(origin, ray, object, COLUMN_FLOOR_Y);
  if (bottomDistance > 0 && (nearestDistance < 0 || bottomDistance < nearestDistance)) {
    nearestDistance = bottomDistance;
    nearestNormal = [0, -1, 0];
  }

  if (nearestDistance <= 0 || nearestNormal == null) {
    return undefined;
  }

  return {
    object,
    distance: nearestDistance,
    normal: nearestNormal,
  };
}

function intersectColumnCap(origin: TitleSceneVector3, ray: TitleSceneVector3, object: TitleSceneObject, capY: number): number {
  if (Math.abs(ray[1]) < 0.000001) {
    return -1;
  }
  const t = (capY - origin[1]) / ray[1];
  if (t <= 0) {
    return -1;
  }
  const x = origin[0] + (ray[0] * t);
  const z = origin[2] + (ray[2] * t);
  const dx = x - object.position[0];
  const dz = z - object.position[2];
  if ((dx * dx) + (dz * dz) <= object.radius * object.radius) {
    return t;
  }
  return -1;
}

function meshHit(origin: TitleSceneVector3, ray: TitleSceneVector3, object: TitleSceneMeshObject): TitleSceneObjectHit | undefined {
  const hit = nearestTitleMeshHit(origin, ray, object.mesh);
  return hit == null
    ? undefined
    : {
        object,
        distance: hit.distance,
        normal: hit.normal,
      };
}

function intersectSphere(
  origin: TitleSceneVector3,
  ray: TitleSceneVector3,
  position: TitleSceneVector3,
  radius: number,
): number {
  const oc = sub(origin, position);
  const b = dot(oc, ray);
  const c = dot(oc, oc) - (radius * radius);
  const discriminant = (b * b) - c;
  if (discriminant < 0) {
    return -1;
  }
  const root = Math.sqrt(discriminant);
  const first = -b - root;
  const second = -b + root;
  return first > 0 ? first : second;
}

function intersectColumnSide(origin: TitleSceneVector3, ray: TitleSceneVector3, object: TitleSceneObject): number {
  const dx = origin[0] - object.position[0];
  const dz = origin[2] - object.position[2];
  const a = (ray[0] * ray[0]) + (ray[2] * ray[2]);
  if (a <= COLUMN_RAY_EPSILON) {
    return -1;
  }
  const b = 2 * ((dx * ray[0]) + (dz * ray[2]));
  const c = (dx * dx) + (dz * dz) - (object.radius * object.radius);
  const discriminant = (b * b) - (4 * a * c);
  if (discriminant < 0) {
    return -1;
  }
  const root = Math.sqrt(discriminant);
  const first = (-b - root) / (2 * a);
  const second = (-b + root) / (2 * a);
  return firstColumnRootInRange(origin, ray, object, first, second);
}

function firstColumnRootInRange(
  origin: TitleSceneVector3,
  ray: TitleSceneVector3,
  object: TitleSceneObject,
  first: number,
  second: number,
): number {
  if (columnRootInRange(origin, ray, object, first)) {
    return first;
  }
  return columnRootInRange(origin, ray, object, second) ? second : -1;
}

function columnRootInRange(
  origin: TitleSceneVector3,
  ray: TitleSceneVector3,
  object: TitleSceneObject,
  distance: number,
): boolean {
  const y = origin[1] + (ray[1] * distance);
  return distance > 0 && y >= COLUMN_FLOOR_Y && y <= object.height;
}

function jitter(random: () => number): number {
  return (random() - 0.5) * POSITION_JITTER;
}

function normalize(vector: TitleSceneVector3): TitleSceneVector3 {
  const length = Math.sqrt((vector[0] * vector[0]) + (vector[1] * vector[1]) + (vector[2] * vector[2]));
  return length === 0 ? [0, 0, 0] : [vector[0] / length, vector[1] / length, vector[2] / length];
}

function dot(a: TitleSceneVector3, b: TitleSceneVector3): number {
  return (a[0] * b[0]) + (a[1] * b[1]) + (a[2] * b[2]);
}

function add(a: TitleSceneVector3, b: TitleSceneVector3): TitleSceneVector3 {
  return [a[0] + b[0], a[1] + b[1], a[2] + b[2]];
}

function sub(a: TitleSceneVector3, b: TitleSceneVector3): TitleSceneVector3 {
  return [a[0] - b[0], a[1] - b[1], a[2] - b[2]];
}

function scale(vector: TitleSceneVector3, scalar: number): TitleSceneVector3 {
  return [vector[0] * scalar, vector[1] * scalar, vector[2] * scalar];
}

function seededRandom(seed: number): () => number {
  let state = Math.floor(Math.abs(seed) * PRNG_SEED_SCALE) >>> 0;
  return () => {
    state = (state + PRNG_STEP) >>> 0;
    let mixed = Math.imul(state ^ (state >>> 15), 1 | state);
    mixed ^= mixed + Math.imul(mixed ^ (mixed >>> 7), 61 | mixed);
    return ((mixed ^ (mixed >>> 14)) >>> 0) / PRNG_DIVISOR;
  };
}

import { type Surface } from '@flyingrobots/bijou';

import { averagingBrailleCanvas, type BrailleShaderFn, type BrailleShaderSample, type RGB } from './averaging-braille-canvas.js';
import { type JeditTheme } from './jedit-theme.js';
import {
  generateTitleScene,
  intersectsTitleSceneObjectAlongRay,
  nearestTitleSceneObjectHit,
  type TitleScene,
  type TitleSceneObject,
  type TitleSceneVector3,
} from './title-scene.js';
import { paintTitleLogo, titleLogoCellBounds } from './title-logo.js';
import type { TitleMesh } from './title-mesh.js';

type Vector3 = TitleSceneVector3;
type Color3 = RGB;
export type TitleSceneSphere = TitleSceneObject;
export { titleLogoCellBounds } from './title-logo.js';
export interface TitleFloorLightEffects {
  readonly shadowMultiplier: number;
  readonly contactShadowMultiplier: number;
  readonly causticStrength: number;
}

export interface TitleSceneMaterialColors {
  readonly accent: Color3;
  readonly info: Color3;
  readonly success: Color3;
  readonly ink: Color3;
  readonly muted: Color3;
  readonly surface: Color3;
  readonly floorDark: Color3;
  readonly floorLight: Color3;
}

export interface TitleScreenRenderOptions {
  readonly camAngle: number;
  readonly camRadius?: number;
  readonly sceneSeed?: number;
  readonly mesh?: TitleMesh;
  readonly sceneOverride?: TitleScene;
}

const DEFAULT_CAMERA_RADIUS = 8.5;
const DEFAULT_TITLE_SCENE_SEED = 0.5;
const CAMERA_DRIFT_RATE = 0.005;
const CAMERA_HEIGHT = 2.65;
const CAMERA_TARGET_Y = 0.78;
const LIGHT_AMBIENT = 0.24;
const LIGHT_DIFFUSE = 0.76;
const KEY_LIGHT_DIRECTION: Vector3 = normalize([-1.3, 2.8, -1.7]);
const SPECULAR_POWER = 28;
const SPECULAR_STRENGTH = 0.52;
const RIM_LIGHT_POWER = 2.2;
const RIM_LIGHT_STRENGTH = 0.74;
const REFLECTION_EDGE_BIAS = 0.28;
const REFLECTION_FRESNEL_POWER = 3;
const MIRROR_REFLECTIVITY_THRESHOLD = 0.95;
const MIRROR_REFLECTION_AMOUNT = 1;
const REFLECTION_OBJECT_TINT = 1.18;
const PLANE_FADE_DISTANCE = 36;
const PLANE_MIN_FADE = 0.05;
const PLANE_GRID_SCALE = 0.7;
const SKY_TINT = 1.08;
const SURFACE_REFLECTION_TINT = 0.72;
const SHADOW_RAY_BIAS = 0.03;
const FLOOR_SHADOW_MULTIPLIER = 0.34;
const CONTACT_SHADOW_RADIUS_SCALE = 1.32;
const CONTACT_SHADOW_STRENGTH = 0.72;
const CONTACT_SHADOW_POWER = 1.75;
const CONTACT_SHADOW_MIN_MULTIPLIER = 0.18;
const CAUSTIC_RADIUS_SCALE = 2.4;
const CAUSTIC_WAVE_FREQUENCY = 3.1;
const CAUSTIC_WAVE_SECONDARY_FREQUENCY = 1.7;
const CAUSTIC_TIME_RATE = 0.9;
const CAUSTIC_STRENGTH = 0.45;
const MAX_CAUSTIC_STRENGTH = 0.42;
const LUMINANCE_RED_WEIGHT = 0.2126;
const LUMINANCE_GREEN_WEIGHT = 0.7152;
const LUMINANCE_BLUE_WEIGHT = 0.0722;

export function renderTitleScreen(
  cols: number,
  rows: number,
  time: number,
  theme: JeditTheme,
  options: TitleScreenRenderOptions,
): Surface {
  const {
    camAngle,
    camRadius = DEFAULT_CAMERA_RADIUS,
    sceneSeed = DEFAULT_TITLE_SCENE_SEED,
    mesh,
    sceneOverride,
  } = options;
  const colors = titleSceneMaterialColors(theme);
  const scene = sceneOverride ?? generateTitleScene(sceneSeed, colors, mesh);

  const shader: BrailleShaderFn = ({ u, v, time: frameTime }) => {
    return sceneSampleAt(u, v, cols, rows, frameTime, camAngle, camRadius, scene.objects, colors);
  };

  const surface = averagingBrailleCanvas(cols, rows, shader, time);
  paintTitleLogo(surface, titleLogoCellBounds(cols, rows), colors, time);
  return surface;
}

export function titleSceneMaterialColors(theme: JeditTheme): TitleSceneMaterialColors {
  const baseColors = fixedTitleSceneBaseColors(theme);
  const floorColors = orderedFloorMaterialColors(baseColors.ink, baseColors.muted);

  return {
    ...baseColors,
    floorDark: floorColors.dark,
    floorLight: floorColors.light,
  };
}

function fixedTitleSceneBaseColors(_theme: JeditTheme): Omit<TitleSceneMaterialColors, 'floorDark' | 'floorLight'> {
  return {
    accent: [224, 113, 63],
    info: [78, 195, 224],
    success: [112, 216, 167],
    ink: [222, 232, 232],
    muted: [55, 75, 88],
    surface: [5, 7, 12],
  };
}

function sceneSampleAt(
  u: number,
  v: number,
  cols: number,
  rows: number,
  time: number,
  camAngle: number,
  camRadius: number,
  objects: readonly TitleSceneObject[],
  colors: TitleSceneMaterialColors,
): BrailleShaderSample {
  const aspect = cols / Math.max(1, rows);
  const rx = (u * 2 - 1) * aspect;
  const ry = v * 2 - 1;
  const finalAngle = camAngle + (time * CAMERA_DRIFT_RATE);
  const origin: Vector3 = [
    Math.sin(finalAngle) * camRadius,
    CAMERA_HEIGHT,
    Math.cos(finalAngle) * camRadius,
  ];
  const ray = getRayDir(origin, [0, CAMERA_TARGET_Y, 0], [rx, -ry - 0.2, 2.7]);
  const objectHit = nearestTitleSceneObjectHit(origin, ray, objects);
  const planeDistance = -origin[1] / ray[1];

  if (objectHit != null && (planeDistance <= 0 || objectHit.distance < planeDistance)) {
    const point = add(origin, scale(ray, objectHit.distance));
    const normal = objectHit.normal;
    const reflectionRay = reflect(ray, normal);
    const reflectionColor = reflectedEnvironmentColor(add(point, scale(normal, SHADOW_RAY_BIAS)), reflectionRay, colors, objects, time, objectHit.object);
    const fresnel = Math.pow(1 - Math.max(0, dot(scale(ray, -1), normal)), REFLECTION_FRESNEL_POWER);
    const reflectionAmount = titleObjectReflectionAmount(objectHit.object.reflectivity, fresnel);
    return {
      on: true,
      fgRGB: addColor(
        mixColor(shadedObjectColor(objectHit, ray, colors), reflectionColor, reflectionAmount),
        objectRimLightColor(objectHit, ray, colors),
      ),
      bgRGB: colors.surface,
    };
  }

  if (planeDistance > 0) {
    const point = add(origin, scale(ray, planeDistance));
    const fade = Math.max(0, 1 - (planeDistance / PLANE_FADE_DISTANCE));
    const grid = (Math.floor(point[0] * PLANE_GRID_SCALE) + Math.floor(point[2] * PLANE_GRID_SCALE)) % 2 === 0;
    if (fade > PLANE_MIN_FADE) {
      const floorColor = grid ? colors.floorLight : colors.floorDark;
      const effects = titleFloorLightEffectsAt(point, objects, time);
      const materialColor = mixColor(colors.surface, floorColor, fade);
      const causticColor = scaleColor(colors.info, effects.causticStrength * fade);
      return {
        on: true,
        fgRGB: addColor(scaleColor(materialColor, effects.shadowMultiplier * effects.contactShadowMultiplier), causticColor),
        bgRGB: colors.surface,
      };
    }
  }

  const background = scaleColor(colors.surface, SKY_TINT);
  return {
    on: false,
    fgRGB: background,
    bgRGB: background,
  };
}

function titleObjectReflectionAmount(reflectivity: number, fresnel: number): number {
  if (reflectivity >= MIRROR_REFLECTIVITY_THRESHOLD) {
    return MIRROR_REFLECTION_AMOUNT;
  }
  return reflectivity * (REFLECTION_EDGE_BIAS + ((1 - REFLECTION_EDGE_BIAS) * fresnel));
}

function reflectedEnvironmentColor(
  point: Vector3,
  ray: Vector3,
  colors: TitleSceneMaterialColors,
  objects: readonly TitleSceneObject[],
  time: number,
  ignoredObject: TitleSceneObject,
): Color3 {
  const objectHit = nearestTitleSceneObjectHit(point, ray, objects, ignoredObject);
  if (objectHit != null) {
    return scaleColor(shadedObjectColor(objectHit, ray, colors), REFLECTION_OBJECT_TINT);
  }

  const planeDistance = -point[1] / ray[1];
  if (planeDistance > 0) {
    const reflectedPoint = add(point, scale(ray, planeDistance));
    const fade = Math.max(0, 1 - (planeDistance / PLANE_FADE_DISTANCE));
    const grid = (Math.floor(reflectedPoint[0] * PLANE_GRID_SCALE) + Math.floor(reflectedPoint[2] * PLANE_GRID_SCALE)) % 2 === 0;
    const floorColor = grid ? colors.floorLight : colors.floorDark;
    const effects = titleFloorLightEffectsAt(reflectedPoint, objects, time);
    const materialColor = mixColor(colors.surface, floorColor, fade);
    const causticColor = scaleColor(colors.info, effects.causticStrength * fade);
    return scaleColor(
      addColor(scaleColor(materialColor, effects.shadowMultiplier * effects.contactShadowMultiplier), causticColor),
      SURFACE_REFLECTION_TINT,
    );
  }

  return mixColor(scaleColor(colors.surface, SKY_TINT), colors.muted, Math.max(0, ray[1]));
}

function shadedObjectColor(
  objectHit: { readonly object: TitleSceneObject; readonly normal: Vector3 },
  ray: Vector3,
  colors: TitleSceneMaterialColors,
): Color3 {
  const light = Math.max(0, dot(objectHit.normal, KEY_LIGHT_DIRECTION));
  const intensity = LIGHT_AMBIENT + (light * LIGHT_DIFFUSE);
  const viewDirection = scale(ray, -1);
  const halfVector = normalize(add(KEY_LIGHT_DIRECTION, viewDirection));
  const specular = Math.pow(Math.max(0, dot(objectHit.normal, halfVector)), SPECULAR_POWER) * SPECULAR_STRENGTH;
  return addColor(scaleColor(objectHit.object.color, intensity), scaleColor(colors.ink, specular));
}

function objectRimLightColor(
  objectHit: { readonly object: TitleSceneObject; readonly normal: Vector3 },
  ray: Vector3,
  colors: TitleSceneMaterialColors,
): Color3 {
  const viewAlignment = Math.max(0, dot(objectHit.normal, scale(ray, -1)));
  const strength = Math.pow(1 - viewAlignment, RIM_LIGHT_POWER) * RIM_LIGHT_STRENGTH;
  const color = objectHit.object.reflectivity >= MIRROR_REFLECTIVITY_THRESHOLD ? colors.ink : colors.info;
  return scaleColor(color, strength);
}

export function titleFloorLightEffectsAt(
  point: Vector3,
  objects: readonly TitleSceneObject[],
  time: number,
): TitleFloorLightEffects {
  return {
    shadowMultiplier: titleFloorPointInShadow(point, objects) ? FLOOR_SHADOW_MULTIPLIER : 1,
    contactShadowMultiplier: titleFloorContactShadowMultiplierAt(point, objects),
    causticStrength: titleFloorCausticStrengthAt(point, objects, time),
  };
}

function titleFloorPointInShadow(point: Vector3, objects: readonly TitleSceneObject[]): boolean {
  const shadowOrigin = add(point, [0, SHADOW_RAY_BIAS, 0]);
  return objects.some((object) => intersectsTitleSceneObjectAlongRay(shadowOrigin, KEY_LIGHT_DIRECTION, object));
}

function titleFloorCausticStrengthAt(
  point: Vector3,
  objects: readonly TitleSceneObject[],
  time: number,
): number {
  let strength = 0;
  for (const object of objects) {
    if (object.reflectivity <= 0) {
      continue;
    }
    const dx = point[0] - object.position[0];
    const dz = point[2] - object.position[2];
    const distance = Math.sqrt((dx * dx) + (dz * dz));
    const radius = (object.footprintRadius ?? object.radius) * CAUSTIC_RADIUS_SCALE;
    const falloff = Math.max(0, 1 - (distance / radius));
    if (falloff <= 0) {
      continue;
    }
    const wave = (Math.sin(
      (dx * CAUSTIC_WAVE_FREQUENCY)
        + (dz * CAUSTIC_WAVE_SECONDARY_FREQUENCY)
        + (time * CAUSTIC_TIME_RATE),
    ) + 1) / 2;
    strength += falloff * wave * object.reflectivity * CAUSTIC_STRENGTH;
  }
  return Math.min(MAX_CAUSTIC_STRENGTH, strength);
}

function titleFloorContactShadowMultiplierAt(point: Vector3, objects: readonly TitleSceneObject[]): number {
  let strength = 0;
  for (const object of objects) {
    const dx = point[0] - object.position[0];
    const dz = point[2] - object.position[2];
    const falloff = Math.max(0, 1 - (Math.sqrt((dx * dx) + (dz * dz)) / (object.footprintRadius * CONTACT_SHADOW_RADIUS_SCALE)));
    strength = Math.max(strength, Math.pow(falloff, CONTACT_SHADOW_POWER) * CONTACT_SHADOW_STRENGTH);
  }
  return Math.max(CONTACT_SHADOW_MIN_MULTIPLIER, 1 - strength);
}

function orderedFloorMaterialColors(
  first: Color3,
  second: Color3,
): { readonly dark: Color3; readonly light: Color3 } {
  return colorLuminance(first) <= colorLuminance(second)
    ? { dark: first, light: second }
    : { dark: second, light: first };
}

function colorLuminance(color: Color3): number {
  return (color[0] * LUMINANCE_RED_WEIGHT)
    + (color[1] * LUMINANCE_GREEN_WEIGHT)
    + (color[2] * LUMINANCE_BLUE_WEIGHT);
}

function mixColor(from: Color3, to: Color3, ratio: number): Color3 {
  const clamped = Math.max(0, Math.min(1, ratio));
  return [
    Math.round(from[0] + ((to[0] - from[0]) * clamped)),
    Math.round(from[1] + ((to[1] - from[1]) * clamped)),
    Math.round(from[2] + ((to[2] - from[2]) * clamped)),
  ];
}

function scaleColor(color: Color3, scalar: number): Color3 {
  return [
    Math.max(0, Math.min(255, Math.round(color[0] * scalar))),
    Math.max(0, Math.min(255, Math.round(color[1] * scalar))),
    Math.max(0, Math.min(255, Math.round(color[2] * scalar))),
  ];
}

function addColor(a: Color3, b: Color3): Color3 {
  return [
    Math.min(255, a[0] + b[0]),
    Math.min(255, a[1] + b[1]),
    Math.min(255, a[2] + b[2]),
  ];
}

function getRayDir(origin: Vector3, target: Vector3, screenCoords: Vector3): Vector3 {
  const forward = normalize(sub(target, origin));
  const right = normalize(cross(forward, [0, 1, 0]));
  const up = cross(right, forward);
  return normalize(add(add(scale(right, screenCoords[0]), scale(up, screenCoords[1])), scale(forward, screenCoords[2])));
}

function cross(a: Vector3, b: Vector3): Vector3 {
  return [
    (a[1] * b[2]) - (a[2] * b[1]),
    (a[2] * b[0]) - (a[0] * b[2]),
    (a[0] * b[1]) - (a[1] * b[0]),
  ];
}

function normalize(vector: Vector3): Vector3 {
  const length = Math.sqrt((vector[0] * vector[0]) + (vector[1] * vector[1]) + (vector[2] * vector[2]));
  return length === 0 ? [0, 0, 0] : [vector[0] / length, vector[1] / length, vector[2] / length];
}

function dot(a: Vector3, b: Vector3): number {
  return (a[0] * b[0]) + (a[1] * b[1]) + (a[2] * b[2]);
}

function add(a: Vector3, b: Vector3): Vector3 {
  return [a[0] + b[0], a[1] + b[1], a[2] + b[2]];
}

function sub(a: Vector3, b: Vector3): Vector3 {
  return [a[0] - b[0], a[1] - b[1], a[2] - b[2]];
}

function scale(vector: Vector3, scalar: number): Vector3 {
  return [vector[0] * scalar, vector[1] * scalar, vector[2] * scalar];
}

function reflect(ray: Vector3, normal: Vector3): Vector3 {
  return sub(ray, scale(normal, 2 * dot(ray, normal)));
}

import { createSurface, stringToSurface, type Surface } from '@flyingrobots/bijou';
import { clipToWidth } from '@flyingrobots/bijou-tui';
import { basename } from 'node:path';

import type { FileEntry } from '../adapters/filesystem.js';
import { JEDIT_MARKDOWN_PREVIEW_TOGGLE_LABEL, JEDIT_SETTINGS_TOGGLE_LABEL, JEDIT_THEME_TOGGLE_LABEL } from '../app/keybindings.js';
import type { I18nPort } from '../ports/i18n.js';
import type { JeditStyleToken } from './jedit-theme.js';
import type { DrawerKind } from './drawer-layout.js';
import { hasFocusablePeers, type FocusPane } from './panel-focus.js';

type ViewMode = 'source' | 'preview';
type EditorMode = 'normal' | 'insert';
type PendingNormal = 'c' | 'd' | 'g' | 'y';

const THEME_HINT = `${JEDIT_THEME_TOGGLE_LABEL} theme`;

export interface WorkspaceTitleState {
  readonly cwd: string;
  readonly editorPath?: string;
  readonly editorDirty: boolean;
  readonly selectedEntry?: FileEntry;
}

export interface WorkspaceFooterState {
  readonly i18n: I18nPort;
  readonly focusPane: FocusPane;
  readonly fileDrawerOpen: boolean;
  readonly graftDrawerOpen: boolean;
  readonly viewMode: ViewMode;
  readonly markdownPreviewActive: boolean;
  readonly settingsOpen: boolean;
  readonly editorMode?: EditorMode;
  readonly pendingNormal?: PendingNormal;
  readonly cwd: string;
  readonly selectedEntry?: FileEntry;
  readonly editorPath?: string;
  readonly graftPath?: string;
  readonly graftSelection?: {
    readonly kind: string;
    readonly name: string;
    readonly startLine: number;
  };
}

export function activeWorkspaceTitle(state: WorkspaceTitleState): string {
  if (state.editorPath != null) {
    const mark = state.editorDirty ? ' *' : '';
    return `${basename(state.editorPath)}${mark}`;
  }

  if (state.selectedEntry?.kind === 'file') {
    return state.selectedEntry.name;
  }

  return displayName(state.cwd);
}

export function centerLine(text: string, width: number): string {
  const clipped = clipToWidth(text, width);
  const visible = [...clipped].length;
  if (visible >= width) {
    return clipped;
  }

  const left = Math.floor((width - visible) / 2);
  const right = width - visible - left;
  return `${' '.repeat(left)}${clipped}${' '.repeat(right)}`;
}

export function renderWorkspaceFooter(state: WorkspaceFooterState, width: number, background: JeditStyleToken): Surface {
  const surface = createSurface(width, 2);
  fillSurface(surface, background);

  const [primary, secondary] = workspaceFooterLines(state);
  const primarySurface = stringToSurface(fitLine(primary, width), width, 1);
  const secondarySurface = stringToSurface(fitLine(secondary, width), width, 1);
  applyBackground(primarySurface, background);
  applyBackground(secondarySurface, background);

  // Logical positioning for RTL/LTR
  const isRtl = state.i18n.direction === 'rtl';
  surface.blit(primarySurface, isRtl ? width - primarySurface.width : 0, 0);
  surface.blit(secondarySurface, isRtl ? width - secondarySurface.width : 0, 1);
  return surface;
}

export function workspaceFooterLine(state: WorkspaceFooterState): string {
  return workspaceFooterLines(state)[0];
}

export function workspaceFooterLines(state: WorkspaceFooterState): readonly [string, string] {
  const modeKey = interactionModeKey(state);
  const modeLabel = state.i18n.t(`footer.mode.${modeKey}`).toUpperCase();
  const detail = footerDetail(state);

  const primary = detail.length > 0 ? `${modeLabel} ${detail}` : modeLabel;
  const secondary = footerContextLine(state);

  return [primary, secondary];
}

function interactionModeKey(state: WorkspaceFooterState): string {
  if (state.settingsOpen) {
    return 'settings';
  }

  if (state.focusPane === 'files' && state.fileDrawerOpen) {
    return 'files';
  }

  if (state.focusPane === 'graft' && state.graftDrawerOpen) {
    return 'graft';
  }

  if (state.viewMode === 'preview' && state.markdownPreviewActive) {
    return 'preview';
  }

  if (state.editorMode != null) {
    return state.editorMode;
  }

  return 'browse';
}

function footerDetail(state: WorkspaceFooterState): string {
  const t = (key: string) => state.i18n.t(`footer.hints.${key}`);

  if (state.settingsOpen) {
    return footerHints([t('j_k_move'), t('enter_change'), `${JEDIT_SETTINGS_TOGGLE_LABEL} close`, 'esc close']);
  }

  if (state.focusPane === 'files' && state.fileDrawerOpen) {
    return drawerFooterDetail(state, 'files');
  }

  if (state.focusPane === 'graft' && state.graftDrawerOpen) {
    return drawerFooterDetail(state, 'graft');
  }

  if (state.viewMode === 'preview' && state.markdownPreviewActive) {
    return footerHints([t('j_k_scroll'), `${JEDIT_MARKDOWN_PREVIEW_TOGGLE_LABEL} source`, THEME_HINT, focusHint(state), 'ctrl+b files', 'ctrl+g graft']);
  }

  if (state.editorMode === 'insert') {
    return footerHints([t('text_input'), t('esc_normal'), t('ctrl_s_save'), THEME_HINT, insertTabHint(state)]);
  }

  if (state.editorMode === 'normal') {
    return normalFooterDetail(state);
  }

  return footerHints([focusHint(state), THEME_HINT, 'ctrl+b files', 'ctrl+g graft']);
}

function drawerFooterDetail(state: WorkspaceFooterState, kind: DrawerKind): string {
  const t = (key: string) => state.i18n.t(`footer.hints.${key}`);

  if (kind === 'files') {
    return footerHints([t('j_k_move'), 'enter open', 'backspace up', 'ctrl+b close', THEME_HINT, focusHint(state)]);
  }

  return footerHints([t('j_k_move'), 'enter jump', 'r refresh', 'ctrl+g close', THEME_HINT, focusHint(state)]);
}

function normalFooterDetail(state: WorkspaceFooterState): string {
  const pending = state.pendingNormal;
  if (pending != null) {
    return pendingNormalFooterDetail(pending);
  }

  const previewHint = state.markdownPreviewActive ? `${JEDIT_MARKDOWN_PREVIEW_TOGGLE_LABEL} preview` : 'ctrl+s save';
  return footerHints(['i insert', 'o open line', previewHint, THEME_HINT, focusHint(state)]);
}

function pendingNormalFooterDetail(pending: PendingNormal): string {
  if (pending === 'c') {
    return chordFooterHints('c', ['cc line', 'cw word', 'ce word-end', 'c0 start', 'c$ end']);
  }

  if (pending === 'd') {
    return chordFooterHints('d', ['dd line', 'dw word', 'de word-end', 'd0 start', 'd$ end']);
  }

  if (pending === 'y') {
    return chordFooterHints('y', ['yy line', 'yw word', 'ye word-end', 'y0 start', 'y$ end']);
  }

  return chordFooterHints('g', ['gg top', 'esc cancel']);
}

function footerContextLine(state: WorkspaceFooterState): string {
  if (state.settingsOpen) {
    return 'settings';
  }

  if (state.focusPane === 'files' && state.fileDrawerOpen) {
    return state.selectedEntry?.path ?? state.cwd;
  }

  if (state.focusPane === 'graft' && state.graftDrawerOpen) {
    if (state.graftSelection != null && state.graftPath != null) {
      return `${state.graftPath}:${state.graftSelection.startLine} ${state.graftSelection.kind} ${state.graftSelection.name}`;
    }

    if (state.graftPath != null) {
      return state.graftPath;
    }

    return 'open a file to inspect it';
  }

  if (state.editorPath != null) {
    return state.editorPath;
  }

  return state.cwd;
}

function displayName(path: string): string {
  const name = basename(path);
  return name.length > 0 ? name : path;
}

function fillSurface(surface: Surface, token: JeditStyleToken) {
  surface.fill({
    char: ' ',
    bg: token.bg,
    bgRGB: token.bgRGB,
    empty: false,
  });
}

function applyBackground(surface: Surface, token: JeditStyleToken) {
  for (let y = 0; y < surface.height; y += 1) {
    for (let x = 0; x < surface.width; x += 1) {
      const cell = surface.get(x, y);
      surface.set(x, y, {
        ...cell,
        char: cell.char.length > 0 ? cell.char : ' ',
        bg: token.bg,
        bgRGB: token.bgRGB,
        empty: false,
      });
    }
  }
}

function fitLine(text: string, width: number): string {
  const clipped = clipToWidth(text, width);
  const visible = [...clipped].length;
  if (visible >= width) {
    return clipped;
  }

  return clipped.padEnd(width, ' ');
}

function footerHasFocusablePeers(state: WorkspaceFooterState): boolean {
  return hasFocusablePeers({
    fileDrawerOpen: state.fileDrawerOpen,
    graftDrawerOpen: state.graftDrawerOpen,
    hasEditor: state.editorPath != null,
    focusPane: state.focusPane,
  });
}

function focusHint(state: WorkspaceFooterState): string | undefined {
  return footerHasFocusablePeers(state) ? 'tab focus' : undefined;
}

function insertTabHint(state: WorkspaceFooterState): string {
  return footerHasFocusablePeers(state) ? 'tab focus' : 'tab indent';
}

function footerHints(parts: ReadonlyArray<string | undefined>): string {
  const filtered = parts.filter((part): part is string => part != null && part.trim().length > 0);
  return `[${filtered.join(' · ')}]`;
}

function chordFooterHints(chord: string, suggestions: readonly string[]): string {
  return `${chord} [${suggestions.join(' · ')}]`;
}

import type { Cell, Surface } from '@flyingrobots/bijou';
import type { WorkspaceLayout } from './drawer-layout.js';
import type { FocusPane } from './panel-focus.js';
import type { JeditStyleToken } from './jedit-theme.js';

const MIN_EDGE_HEIGHT = 0;

export interface ActivePaneEdgeState {
  readonly focusPane: FocusPane;
  readonly fileDrawerOpen: boolean;
  readonly graftDrawerOpen: boolean;
  readonly hasEditor: boolean;
}

export interface ActivePaneEdgeBounds {
  readonly top: number;
  readonly height: number;
}

type CellStyle = Pick<Cell, 'fg' | 'bg' | 'fgRGB' | 'bgRGB' | 'modifiers'>;

export function paintActivePaneEdge(
  surface: Surface,
  layout: WorkspaceLayout,
  state: ActivePaneEdgeState,
  token: JeditStyleToken,
  bounds: ActivePaneEdgeBounds,
): void {
  const x = activePaneEdgeX(layout, state);
  if (x == null || x < 0 || x >= surface.width || token.char == null || token.char.length === 0) {
    return;
  }

  const top = Math.max(0, bounds.top);
  const bottom = Math.min(surface.height, top + Math.max(MIN_EDGE_HEIGHT, bounds.height));
  for (let y = top; y < bottom; y += 1) {
    const cell = surface.get(x, y);
    surface.set(x, y, {
      ...cell,
      char: token.char,
      ...edgeStyle(cell, token),
      empty: false,
    });
  }
}

export function activePaneEdgeX(layout: WorkspaceLayout, state: ActivePaneEdgeState): number | undefined {
  if (state.focusPane === 'files') {
    return state.fileDrawerOpen && layout.fileDrawer.width > 0 ? layout.fileDrawer.x : undefined;
  }

  if (state.focusPane === 'graft') {
    return state.graftDrawerOpen && layout.graftDrawer.width > 0 ? layout.graftDrawer.x : undefined;
  }

  return state.hasEditor && layout.viewer.width > 0 ? layout.viewer.x : undefined;
}

function edgeStyle(cell: Cell, token: JeditStyleToken): CellStyle {
  return {
    fg: token.fg ?? cell.fg,
    bg: token.bg ?? cell.bg,
    fgRGB: token.fgRGB ?? cell.fgRGB,
    bgRGB: token.bgRGB ?? cell.bgRGB,
    modifiers: token.modifiers == null ? cell.modifiers : [...token.modifiers],
  };
}
